  const parseHash = () => {
    const raw = location.hash.replace(/^#\/?/, "");
    const [path, query] = raw.split("?");
    const parts = path.split("/").filter(Boolean);
    const params = new URLSearchParams(query || "");
    return { parts, params };
  };
  const setNav = (key) => document.querySelectorAll("[data-nav]").forEach((a) => a.classList.toggle("active", a.dataset.nav === key));

  // animated waving UAE flag for the national-identity tab (CSS only)
  const uaeFlag = () => {
    const n = 24;
    const slices = Array.from({ length: n }, (_, i) => `<i class="${i < n / 4 ? "r" : "s"}" style="animation-delay:${(-i * 0.09).toFixed(2)}s"></i>`).join("");
    return `<div class="uae-flag" role="img" aria-label="علم دولة الإمارات العربية المتحدة"><span class="uf-pole"></span><div class="uf-cloth">${slices}</div></div>`;
  };
  const slideEmbed = (url) => {
    if (/^resources\/.+\.html$/i.test(url || "")) return new URL(url, location.href.split("#")[0]).href;
    try {
      const u = new URL(url);
      let m;
      if (u.hostname === "docs.google.com" && (m = u.pathname.match(/\/presentation\/d\/([^/]+)/))) return `https://docs.google.com/presentation/d/${m[1]}/embed?start=false&loop=false&delayms=60000`;
      if (u.hostname === "drive.google.com" && (m = u.pathname.match(/\/file\/d\/([^/]+)/))) return `https://drive.google.com/file/d/${m[1]}/preview`;
      if (u.hostname.endsWith("onedrive.live.com") && u.pathname.includes("embed")) return url;
      if (u.hostname.endsWith("canva.com") && u.pathname.includes("/view")) return url.includes("embed") ? url : url.split("?")[0] + "?embed";
      return null;
    } catch (e) { return null; }
  };
  const FILE_BUCKET = "lesson-files";
  const extOf = (p) => (String(p || "").split(".").pop() || "").toLowerCase();
  async function fileUrl(path) {
    const { data, error } = await sb.storage.from(FILE_BUCKET).createSignedUrl(path, 3600);
    if (error) { toast("تعذّر فتح الملف"); return null; }
    return data.signedUrl;
  }
  const officeView = (u) => "https://view.officeapps.live.com/op/embed.aspx?src=" + encodeURIComponent(u);
