  async function pageIgcsePaper(id) {
    setNav("grades"); state.pageSubject = "igcse"; setTheme();
    const P = igGetPaper(id); if (!P) { location.hash = "#/igcse"; return; }
    const pick = { A: (P.qs.find((q) => q.sec === "A") || {}).n, B: (P.qs.find((q) => q.sec === "B") || {}).n };
    const key = "hiraa.ig." + id; let ans = {}; try { ans = JSON.parse(localStorage.getItem(key) || "{}"); } catch (e) {}
    const chosen = () => P.qs.filter((q) => q.sec === "C" || q.n === pick[q.sec]);
    const qHtml = (q) => { const a = ans[q.n] || {};
      return `<article class="ig-q" data-n="${q.n}"><header><span class="ig-qn">Question ${q.n}</span><b>${esc(q.topic)}</b><small>${q.realSec ? "Section " + q.realSec + " · " : ""}Set passage: ${esc(q.passage)}</small></header>
        <div class="ig-part"><p><b>(a)</b> ${esc(q.a.q)} <em>(${q.a.o ? 1 : q.a.max})</em></p>${q.a.o ? `<div class="ig-opts">${q.a.o.map((o, i) => `<label><input type="radio" name="a${q.n}" value="${i}" ${a.a === i ? "checked" : ""}> ${esc(o)}</label>`).join("")}</div>` : `<textarea rows="2" data-f="a">${esc(a.a || "")}</textarea>`}</div>
        <div class="ig-part"><p><b>(b)</b> ${esc(q.b.q)} <em>(${q.b.max})</em></p><textarea rows="3" data-f="b">${esc(a.b || "")}</textarea></div>
        <div class="ig-part"><p><b>(c)</b> ${esc(q.c.q)} <em>(6)</em></p><textarea rows="7" data-f="c">${esc(a.c || "")}</textarea><small class="ig-wc"></small></div>
        <div class="ig-part"><div class="ig-pass" data-igp="${esc(q.passage)}" data-top="${esc(q.topic.split(" ")[0])}"><b>📖 ${esc(q.passage)}</b></div><p><b>(d)</b> ${esc(q.d.q)} <em>(12)</em></p><p class="ig-tip">In your answer you should: refer to the set passage · consider different points of view · reach a justified conclusion.</p><textarea rows="12" data-f="d">${esc(a.d || "")}</textarea><small class="ig-wc"></small></div></article>`; };
    const render = () => {
      h(`<section class="page-head ig-head" dir="ltr"><div class="wrap"><div class="crumbs"><a href="#/igcse">IGCSE Islamic Studies</a></div><h1>${P.title}</h1>
          <p class="muted">${/^U/.test(P.id) ? "Answer both questions." : "Answer one question from Section A, one from Section B and both questions in Section C."} Your answers save automatically on this device. The set passage is shown above every 12-mark question.</p>
          <div class="ig-timer" id="igT">⏱ 0:00</div></div></section>
        <section class="section" dir="ltr" style="padding-top:18px"><div class="wrap ig-paper-wrap">
          ${["A", "B"].filter((s) => P.qs.filter((q) => q.sec === s).length > 1).map((s) => `<div class="ig-choose"><b>Section ${s}:</b> ${P.qs.filter((q) => q.sec === s).map((q) => `<button data-pick="${s}:${q.n}" aria-pressed="${pick[s] === q.n}">Q${q.n} · ${esc(q.topic.replace(/^\d\.\d\s/, ""))}</button>`).join("")}</div>`).join("")}
          ${chosen().map(qHtml).join("")}
          <div class="ig-submit"><button class="btn btn-primary" id="igSend">Submit and see my feedback</button></div></div></section>`);
      document.querySelectorAll("[data-pick]").forEach((b) => b.onclick = () => { const [s, n] = b.dataset.pick.split(":"); pick[s] = +n; save(); render(); });
      document.querySelectorAll(".ig-q").forEach((el) => { const n = +el.dataset.n;
        el.querySelectorAll("input[type=radio]").forEach((r) => r.onchange = () => { ans[n] = ans[n] || {}; ans[n].a = +r.value; save(); });
        el.querySelectorAll("textarea").forEach((t) => { const wc = t.nextElementSibling && t.nextElementSibling.classList.contains("ig-wc") ? t.nextElementSibling : null;
          const upd = () => { if (wc) wc.textContent = (t.value.trim() ? t.value.trim().split(/\s+/).length : 0) + " words"; };
          upd(); t.oninput = () => { ans[n] = ans[n] || {}; ans[n][t.dataset.f] = t.value; upd(); save(); }; }); });
      document.getElementById("igSend").onclick = submit;
      igFillPassages(document.getElementById("main"));
    };
    const save = () => { try { localStorage.setItem(key, JSON.stringify(ans)); } catch (e) {} };
    const t0 = Date.now(); state._igTm && clearInterval(state._igTm);
    state._igTm = setInterval(() => { const el = document.getElementById("igT"); if (!el || !location.hash.startsWith("#/igcse-paper")) { clearInterval(state._igTm); return; } const s = Math.floor((Date.now() - t0) / 1000); el.textContent = `⏱ ${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")} · suggested 75 min for this practice`; }, 1000);
    const submit = async () => {
      const Q = chosen(); if (!confirm("Submit your answers?")) return;
      const marks = {}; let tot = 0, mx = 0; Q.forEach((q) => { marks[q.n] = igMark(q, ans[q.n]); tot += marks[q.n].total; mx += marks[q.n].max; });
      if (state.session && isStudent()) await sb.from("igcse_attempts").insert({ paper: P.id, answers: ans, marks, total: tot, max: mx });
      clearInterval(state._igTm); showResult(Q, marks, tot, mx);
    };
    const showResult = (Q, marks, tot, mx) => {
      const pct = Math.round((tot / mx) * 100), gr = igGrade(pct);
      const ao = { AO1: [0, 0], AO2: [0, 0], AO3: [0, 0] }; Q.forEach((q) => { const m = marks[q.n]; ao.AO1[0] += m.a.got + m.b.got; ao.AO1[1] += m.a.max + m.b.max; ao.AO2[0] += m.c.got; ao.AO2[1] += 6; ao.AO3[0] += m.d.got; ao.AO3[1] += 12; });
      const weakest = Object.entries(ao).sort((x, y) => x[1][0] / x[1][1] - y[1][0] / y[1][1])[0][0];
      const tipAO = { AO1: "Learn key facts, names and dates for each topic — use the exit tickets and flashcards.", AO2: "In 6-mark answers make three points and develop each with 'because… this means…'.", AO3: "In 12-mark answers argue both sides, quote the set passage and finish with a justified conclusion." };
      const chk = (ok, t) => `<li class="${ok ? "ok" : "no"}">${ok ? "✓" : "✗"} ${t}</li>`;
      h(`<section class="page-head ig-head" dir="ltr"><div class="wrap"><div class="crumbs"><a href="#/igcse">IGCSE Islamic Studies</a></div><h1>${P.title} · Results</h1></div></section>
        <section class="section" dir="ltr" style="padding-top:18px"><div class="wrap">
          <div class="ig-res-top"><div class="ig-ring" style="--p:${pct}"><b>${pct}%</b><small>${tot}/${mx}</small></div><div><h2>Indicative grade: ${gr}</h2><p class="muted">Automatic feedback based on the mark-scheme points and levels. Your teacher's marking is final.</p>
            <div class="ig-ao">${Object.entries(ao).map(([k, v]) => `<div><span>${k}</span><i style="--w:${Math.round((v[0] / v[1]) * 100)}%"></i><b>${v[0]}/${v[1]}</b></div>`).join("")}</div>
            <p class="ig-next">🎯 <b>Focus next on ${weakest}:</b> ${tipAO[weakest]}</p></div></div>
          ${Q.map((q) => { const m = marks[q.n], a = ans[q.n] || {};
            return `<article class="ig-q ig-fb"><header><span class="ig-qn">Question ${q.n}</span><b>${esc(q.topic)}</b><span class="ig-qt">${m.total}/${m.max}</span></header>
              <div class="ig-part"><p><b>(a)</b> ${esc(q.a.q)} <em>${m.a.got}/${m.a.max}</em></p>${q.a.o ? `<p>${m.a.got ? "✓ Correct" : `✗ Answer: <b>${esc(q.a.o[q.a.c])}</b>`}</p>` : `<blockquote>${esc(a.a || "—")}</blockquote><p class="ig-model"><b>Accept:</b> ${q.a.pts.map((p) => esc(p[0])).join(" · ")}</p>`}</div>
              <div class="ig-part"><p><b>(b)</b> ${esc(q.b.q)} <em>${m.b.got}/${m.b.max}</em></p><blockquote>${esc(a.b || "—")}</blockquote><p class="ig-model"><b>Model:</b> ${esc(q.b.model)}</p></div>
              <div class="ig-part"><p><b>(c)</b> ${esc(q.c.q)} <em>${m.c.got}/6 · Level ${m.c.lvl}</em></p><p class="ig-lv"><b>${esc(IG_LV_C[m.c.lvl][0])}</b> ➜ ${esc(IG_LV_C[m.c.lvl][1])}</p><blockquote>${esc(a.c || "—")}</blockquote>
                <ul class="ig-chk">${q.c.pts.map((p, i) => chk(m.c.hits[i], "Point about: " + esc(p.slice(0, 3).join(" / ")))).join("")}</ul><p class="ig-model"><b>Model answer:</b> ${esc(q.c.model)}</p></div>
              <div class="ig-part"><p><b>(d)</b> ${esc(q.d.q)} <em>${m.d.got}/12 · Level ${m.d.lvl} of 3</em></p><p class="ig-lv"><b>${esc(IG_LV_D[m.d.lvl][0])}</b> ➜ ${esc(IG_LV_D[m.d.lvl][1])}</p><blockquote>${esc(a.d || "—")}</blockquote>
                <ul class="ig-chk">${chk(m.d.f.some(Boolean), "Arguments supporting the statement")}${chk(m.d.g.some(Boolean), "Arguments against / different views")}${chk(m.d.ref, "Reference to the set passage (" + esc(q.passage) + ")")}${chk(m.d.other, "Other Muslim or non-religious views signposted (e.g. 'However, some Muslims…')")}${chk(m.d.concl, "A justified conclusion")}${chk(m.d.words >= 150, "Developed length (" + m.d.words + " words; aim for 200+ in the exam)")}</ul>
                <p class="ig-model"><b>Model answer (core argument — develop each point further for full marks):</b> ${esc(q.d.model)}</p></div></article>`; }).join("")}
          <div class="ig-submit"><button class="btn btn-ghost" id="igAgain">Try this paper again</button> <a class="btn btn-primary" href="#/igcse">Back to IGCSE</a></div></div></section>`);
      document.getElementById("igAgain").onclick = () => { try { localStorage.removeItem(key); } catch (e) {} ans = {}; pageIgcsePaper(id); };
    };
    render();
  }


  /* ===== One hub for tests: «اختباراتي» + «الاستعداد للامتحان» ===== */
  const testsTabs = (on) => `<div class="tt-tabs"><a href="#/my-tests" class="${on === "mine" ? "on" : ""}">📝 ${CT("كل اختباراتي", "All my tests")}</a><a href="#/prep" class="${on === "prep" ? "on" : ""}">🎯 ${CT("الاستعداد للامتحان", "Exam preparation")}</a></div>`;

  /* ===== «ماذا أفعل الآن؟» for each role ===== */
  async function injectNow() {
    if (!state.session || !state.profile) return;
    const main = document.getElementById("main"); if (!main || main.querySelector(".now-sec")) return;
    const me = state.session.user.id, cards = [];
    const card = (ic, h, b, href, cta) => `<a class="now-card" href="${href}"><span class="now-ic">${ic}</span><div><small>${h}</small><b>${b}</b></div><span class="now-cta">${cta} ←</span></a>`;
    try {
      if (isStudent()) {
        const g = myGradeNow(), tr = state.myTrack || "native", en = tr === "non_native" || LANG === "en", T = (x, y) => (en ? y : x);
        const [{ data: us }, { data: vw }] = await Promise.all([
          sb.from("units").select("term, sort_order, lessons(id, code, title_ar, title_en, sort_order)").eq("year_group", g).eq("track", tr).eq("subject_id", 1).order("term").order("sort_order"),
          sb.from("lesson_views").select("lesson_id").eq("student_id", me)]);
        const seen = new Set((vw || []).map((x) => x.lesson_id));
        const all = (us || []).flatMap((u) => (u.lessons || []).sort((x, y) => x.sort_order - y.sort_order));
        const nx = all.find((l) => !seen.has(l.id));
        if (nx) cards.push(card("📖", T("الدرس التالي", "Next lesson"), esc(en && nx.title_en ? nx.title_en : nx.title_ar), "#/lesson/" + nx.code, T("ادرسه", "Study")));
        const { data: mc } = await sb.from("class_students").select("class_id").eq("student_id", me);
        const cids = (mc || []).map((x) => x.class_id);
        if (cids.length) { const [{ data: op }, { data: at }] = await Promise.all([sb.from("class_assessments").select("assessment_id, assessments(id, title_ar, title_en, kind, year_group)").in("class_id", cids), sb.from("attempts").select("assessment_id").eq("student_id", me)]);
          const done = new Set((at || []).map((x) => x.assessment_id)); const t = (op || []).map((x) => x.assessments).find((x) => x && x.year_group === g && !done.has(x.id));
          if (t) cards.push(card("📝", T("اختبار مطلوب", "Test to take"), esc(en && t.title_en ? t.title_en : t.title_ar), "#/test/" + t.id, T("ابدأ", "Start"))); }
        const term = typeof bookTermNow === "function" ? bookTermNow() : 1, st = enrStageOf(g), u = [...ENRICH, ...ENRICH_AR].find((x) => x.st === st && x.t === term);
        if (u) { const { data: w } = await sb.from("enrich_work").select("status, missions").eq("unit_key", u.k).eq("student_id", me).maybeSingle(); const uu = enrU(u);
          const dn = w ? Object.values(w.missions || {}).filter((x) => x && x.done).length : 0;
          cards.push(card(u.icon, T("المهمة الإثرائية", "Enrichment task"), esc(uu.title) + (w && w.status === "assessed" ? " ✓" : ` · ${dn}/4`), "#/enrich/" + u.k, w ? T("تابع", "Continue") : T("ابدأ", "Start"))); }
      } else if (isParent()) {
        const { data: kl } = await sb.from("parent_links").select("student_id").eq("parent_id", me);
        const kidIds = (kl || []).map((x) => x.student_id); const { data: kp } = kidIds.length ? await sb.from("profiles").select("id, full_name_ar").in("id", kidIds) : { data: [] };
        const kids = kidIds.map((id) => ({ student_id: id, profiles: (kp || []).find((x) => x.id === id) }));
        for (const k of kids) {
          const since = new Date(Date.now() - 7 * 864e5).toISOString();
          const [{ count: lv }, { data: la }] = await Promise.all([sb.from("lesson_views").select("lesson_id", { count: "exact", head: true }).eq("student_id", k.student_id).gte("last_seen", since),
            sb.from("attempts").select("score, max_score, submitted_at, assessments(title_ar)").eq("student_id", k.student_id).not("submitted_at", "is", null).order("submitted_at", { ascending: false }).limit(1)]);
          const nm = (k.profiles && k.profiles.full_name_ar) || "", l0 = (la || [])[0];
          cards.push(`<div class="now-card kid"><span class="now-ic">👦</span><div><b>${esc(nm.split(" ")[0])}</b><small>📖 ${CT(`درس ${lv || 0} دروس هذا الأسبوع`, `${lv || 0} lessons this week`)}</small><small>📝 ${l0 ? `${CT("آخر نتيجة", "Last result")}: ${l0.max_score ? Math.round((l0.score / l0.max_score) * 100) : 0}% — ${esc((l0.assessments && l0.assessments.title_ar) || "")}` : CT("لا اختبارات بعد", "No tests yet")}</small></div></div>`);
        }
      } else if (isStaff()) {
        const { data: wp } = await sb.from("weekly_plans").select("lesson_id, lessons(id, code, title_ar, title_en)").eq("teacher_id", me).order("sent_at", { ascending: false }).limit(1);
        let ls = wp && wp[0] && wp[0].lessons; if (!ls) { try { ls = JSON.parse(localStorage.getItem("tdLast") || "null"); } catch (e) {} }
        if (ls) cards.push(card("▶️", CT("حصة الأسبوع", "This week's lesson"), esc(ls.title_ar || ls.t || ""), "#/lesson/" + ls.code, CT("افتح الدرس والعرض", "Open lesson & deck")));
        const { count: pend } = await sb.from("enrich_work").select("id", { count: "exact", head: true }).eq("status", "submitted");
        cards.push(card("📊", CT("ينتظر تقييمك", "Awaiting your marking"), CT(`${pend || 0} منتجًا إثرائيًّا`, `${pend || 0} enrichment products`), "#/enrich-mark", CT("قيّم", "Assess")));
        if (ls && ls.id) { const { data: r } = await sb.rpc("exit_summary", { p_lesson: ls.id, p_hours: 168 });
          if (r) cards.push(card("🚪", CT("بطاقة الخروج", "Exit ticket"), r.n ? CT(`أجاب ${r.n} · الإتقان ${r.avg ?? 0}%`, `${r.n} answered · mastery ${r.avg ?? 0}%`) + ((r.support || []).length ? CT(` · ${r.support.length} يحتاجون دعمًا`, ` · ${r.support.length} need support`) : "") : CT("لم يحلّها أحد بعد", "No answers yet"), "#/lesson/" + ls.code, CT("التفاصيل", "Details"))); }
      }
    } catch (e) {}
    if (!cards.length || !document.getElementById("main") || main.querySelector(".now-sec")) return;
    const sec = document.createElement("section"); sec.className = "now-sec";
    sec.innerHTML = `<div class="wrap"><h2>🧭 ${CT("ماذا أفعل الآن؟", "What should I do now?")}</h2><div class="now-grid">${cards.join("")}</div></div>`;
    const ph = main.querySelector(".page-head"); if (ph) ph.after(sec); else main.prepend(sec);
  }
  async function independentHome() {
    const box = document.getElementById("indepHome"); if (!box) return;
    const g = myGradeNow(), tr = state.myTrack || "native", me = state.session.user.id;
    if (!g) { box.innerHTML = `<div class="empty"><strong>${CT("لم يُحدَّد صفّك بعد", "Your grade is not set")}</strong></div>`; return; }
    const [{ data: units }, { data: views }, { data: tests }, { data: att }] = await Promise.all([
      sb.from("units").select("term, sort_order, lessons(id, code, title_ar, title_en, sort_order)").eq("year_group", g).eq("track", tr).eq("subject_id", 1).order("term").order("sort_order"),
      sb.from("lesson_views").select("lesson_id").eq("student_id", me),
      sb.from("assessments").select("id, kind, term, title_ar, title_en, track").eq("year_group", g).eq("track", tr).eq("subject_id", 1).in("kind", ["diagnostic", "post"]).order("term"),
      sb.from("attempts").select("assessment_id, score, max_score, submitted_at").eq("student_id", me).not("submitted_at", "is", null)
    ]);
    const seen = new Set((views || []).map((v) => v.lesson_id));
    const ordered = (units || []).flatMap((u) => (u.lessons || []).sort((a, b) => a.sort_order - b.sort_order));
    const next = ordered.find((l) => !seen.has(l.id)) || ordered[0];
    const done = {}; (att || []).forEach((a) => { done[a.assessment_id] = a; });
    const pct = ordered.length ? Math.round((ordered.filter((l) => seen.has(l.id)).length / ordered.length) * 100) : 0;
    const acc = await gradeAccess(g);
    box.innerHTML = (["grant", "class", "staff"].includes(acc) ? "" : `<div class="grade-gate">${accessBox(acc, g).replace('class="empty locked-box access-box"', 'class="gate-in"')}</div>`) + `
      ${next ? `<a class="today-card" href="#/lesson/${esc(next.code)}"><span class="today-tag">${CT("درسك التالي", "Your next lesson")} · Grade ${g}</span><strong>${esc(LANG === "en" && next.title_en ? next.title_en : next.title_ar)}</strong><span class="btn btn-dawn btn-small">${CT("ابدأ", "Start")}</span></a>` : ""}
      <div class="indep-grid">
        <a class="indep-card" href="#/year/${g}?track=${tr}"><span class="ic">📚</span><strong>${CT("دروس صفّي", "My lessons")}</strong><span class="muted">${CT(`أنجزت ${pct}% من دروس السنة`, `${pct}% of the year completed`)}</span><span class="mini-bar"><i style="width:${pct}%"></i></span></a>
        <a class="indep-card" href="#/competitions"><span class="ic">🏆</span><strong>${CT("المسابقات", "Competitions")}</strong><span class="muted">${CT("شارك في مسابقات المنصة", "Join platform competitions")}</span></a>
      </div>
      <h2 style="margin-top:26px">${CT("اختباراتي", "My tests")} <a class="btn btn-ghost btn-small" href="#/my-tests" style="margin-inline-start:8px">${CT("كل اختباراتي ←", "All my tests →")}</a></h2>
      <p class="muted">${CT("خذ التشخيصي في بداية كل فصل دراسي، والبعدي في نهايته، لتعرف مستواك وتقدّمك.", "Take the diagnostic at the start of each term and the post-test at the end to see your progress.")}</p>
      <div class="tp-grid">${[1, 2, 3].map((t) => `<div class="tp-term"><h3>${CT(TERMS[t], "Term " + t)}</h3>${(tests || []).filter((x) => x.term === t).map((x) => `<div class="tp-card ${x.kind}"><div class="tp-head"><strong>${x.kind === "post" ? CT("الاختبار البعدي", "Post-test") : CT("الاختبار التشخيصي", "Diagnostic test")}</strong></div>
        ${done[x.id] ? `<div class="tp-status done">✓ ${done[x.id].score}/${done[x.id].max_score}</div><a class="btn btn-ghost btn-small" href="#/result/${x.id}">${CT("خريطة إتقاني", "My mastery map")}</a>` : `<a class="btn btn-dawn btn-small" href="#/test/${x.id}">${CT("ابدأ الاختبار", "Start the test")}</a>`}</div>`).join("") || "—"}</div>`).join("")}</div>`;
  }

  async function pageAdmin(params) {
    setNav("admin");
    if (!state.session) { location.hash = "#/login"; return; }
    if (!isSuper()) { h('<div class="wrap loading">لوحة التحكم متاحة للمشرف العام فقط.</div>'); return; }
    const year = Number(params.get("year") || 1);
    const track = params.get("track") === "gcse" ? "gcse" : params.get("track") === "igcse" ? "igcse" : params.get("track") === "launch" ? "launch" : params.get("track") === "alevel" ? "alevel" : params.get("track") === "non_native" ? "non_native" : "native";
    const subject = subjOf(params);
    loading();
    const { data: units, error } = await sb.from("units")
      .select("id, term, sort_order, title_ar, is_published, lessons(id, code, sort_order, title_ar, title_en, is_published, lesson_resources(id, kind, part, title_ar, url, storage_path, is_public, audience))")
      .eq("year_group", year).eq("track", track).eq("subject_id", SUBJECTS[subject].id).order("term").order("sort_order");
    if (error) { h(`<div class="wrap loading">${esc(error.message)}</div>`); return; }

    const rows = (units || []).flatMap((u) => (u.lessons || []).sort((a, b) => a.sort_order - b.sort_order).map((l) => ({ u, l })));
    const { data: msgs } = await sb.from("contact_messages").select("id, name, contact, sender_role, message, is_read, created_at").order("created_at", { ascending: false }).limit(50);
    const ROLE_AR = { teacher: "معلم", parent: "ولي أمر", school: "إدارة مدرسة", student: "طالب", other: "أخرى" };
    const unread = (msgs || []).filter((m) => !m.is_read).length;
    const msgsHtml = `<details class="msgs" ${unread ? "open" : ""}><summary><strong>رسائل تواصل معنا</strong> <span class="pill ${unread ? "warn" : ""}">${unread} جديدة من ${(msgs || []).length}</span></summary>
      ${(msgs || []).length ? (msgs || []).map((m) => `<div class="msg ${m.is_read ? "" : "unread"}">
        <div class="msg-head"><strong>${esc(m.name)}</strong> <span class="muted">· ${ROLE_AR[m.sender_role] || ""} · <span dir="ltr">${esc(m.contact)}</span> · ${new Date(m.created_at).toLocaleString(LANG === "en" ? "en-GB" : "ar-AE")}</span></div>
        <p>${esc(m.message)}</p>
        ${m.is_read ? "" : `<button class="btn btn-ghost btn-small" data-read="${m.id}">تمت القراءة</button>`}</div>`).join("") : '<p class="muted">لا توجد رسائل بعد.</p>'}
    </details>`;
    h(`
    <section class="page-head"><div class="wrap" style="padding-bottom:30px">
      <div class="crumbs">لوحة التحكم</div>
      <h1>إدارة المحتوى</h1>
      <p style="margin:6px 0"><a class="btn btn-dawn btn-small" href="#/billing">الاشتراكات والمبيعات</a> <a class="btn btn-ghost btn-small" href="#/access">أذونات المحتوى</a></p>
      <p class="muted">أضف شرائح الدروس وأوراق العمل والفيديوهات بروابطها (Google Drive أو OneDrive أو YouTube)، وتحكّم في نشر الدروس.</p>
    </div></section>
    <section class="section" style="padding-top:34px"><div class="wrap">
      ${msgsHtml}
      <form class="admin-filters" id="filters">
        <div class="field"><label for="fs">المادة</label><select id="fs">${Object.keys(SUBJECTS).map((k) => `<option value="${k}" ${k === subject ? "selected" : ""}>${SUBJECTS[k].name}</option>`).join("")}</select></div>
        <div class="field"><label for="fy">الصف</label><select id="fy">${Array.from({ length: 12 }, (_, i) => `<option value="${i + 1}" ${i + 1 === year ? "selected" : ""}>Grade ${i + 1}</option>`).join("")}</select></div>
        <div class="field"><label for="ft">المسار</label><select id="ft"><option value="native" ${track === "native" ? "selected" : ""}>${TRACKS.native}</option><option value="non_native" ${track === "non_native" ? "selected" : ""}>${TRACKS.non_native}</option><option value="alevel" ${track === "alevel" ? "selected" : ""}>A Level</option><option value="launch" ${track === "launch" ? "selected" : ""}>أبجد</option><option value="gcse" ${track === "gcse" ? "selected" : ""}>GCSE</option><option value="igcse" ${track === "igcse" ? "selected" : ""}>IGCSE</option></select></div>
        <button class="btn btn-ghost" type="submit">عرض</button>
      </form>
      ${rows.length ? `<div class="table-wrap"><table class="admin-table">
        <thead><tr><th>الفصل</th><th>الدرس</th><th>المواد</th><th>منشور</th><th></th></tr></thead>
        <tbody>${rows.map(({ u, l }) => `
          <tr>
            <td>${u.term}</td>
            <td><a href="#/lesson/${esc(l.code)}">${esc(l.title_ar)}</a><br><span class="code">${esc(l.code)}</span></td>
            <td>${(l.lesson_resources || []).map((r) => `<div>${KIND[r.kind]}${r.part ? " ج" + r.part : ""}: ${r.url ? `<a href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.title_ar)}</a>` : `<a href="#" data-file="${esc(r.storage_path)}">${esc(r.title_ar)} (ملف)</a>`}${r.audience === "teacher" ? ' <span class="pill warn">للمعلم</span>' : r.audience === "student" ? ' <span class="pill">للطالب</span>' : ""}${r.is_public ? "" : ' <span class="muted">(للمسجلين)</span>'} <button class="btn btn-ghost btn-small" data-del="${r.id}">حذف</button></div>`).join("") || '<span class="muted">لا شيء بعد</span>'}</td>
            <td><label class="check"><input type="checkbox" data-pub="${l.id}" ${l.is_published ? "checked" : ""}> منشور</label></td>
            <td><button class="btn btn-primary btn-small" data-add="${l.id}" data-title="${esc(l.title_ar)}">إضافة مادة</button></td>
          </tr>`).join("")}</tbody></table></div>`
        : '<div class="empty"><strong>لا توجد دروس لـ${SUBJECTS[subject].name} في هذا الصف والمسار بعد</strong>أرسل الكتاب ليُوزَّع منهجه.</div>'}
    </div></section>
    <dialog id="resDialog">
      <form id="resForm" method="dialog">
        <h2 style="font-size:1.3rem" id="resTitle">إضافة مادة</h2>
        <div class="field"><label for="rk">النوع</label><select id="rk">
          ${Object.keys(KIND).map((k) => `<option value="${k}">${KIND[k]}</option>`).join("")}</select></div>
        <div class="field"><label for="rp">الجزء</label><select id="rp"><option value="">الدرس كله</option><option value="1">الجزء الأول</option><option value="2">الجزء الثاني</option></select></div>
        <div class="field"><label for="ra">لمن هذه المادة؟</label><select id="ra">
          <option value="auto">تلقائي من اسم الملف: «Summary/ملخص/Student» شرائح الطالب، وبقية الشرائح للمعلم، وأوراق العمل للطالب</option>
          <option value="student">🎓 للطالب: شرائح الطالب (ملخص الدرس)، ورقة عمل</option>
          <option value="teacher">🧑‍🏫 للمعلم فقط: شرائح المعلم (عرض الصف)، دليل، إجابات</option>
          <option value="all">للجميع</option></select></div>
        <div class="field"><label for="rt">العنوان</label><input id="rt" required></div>
        <div class="upload-choice">
          <div class="field drop" id="dropZone"><label for="rf">ارفع ملفًا أو عدة ملفات معًا (PowerPoint، PDF، Word، صورة، فيديو، حتى 50 ميغابايت لكل ملف)</label>
            <input id="rf" type="file" multiple accept=".pdf,.ppt,.pptx,.doc,.docx,.xlsx,.png,.jpg,.jpeg,.webp,.mp4,.mp3,.m4a">
            <span class="muted" id="rfName">أو اسحب الملف وأفلته هنا</span></div>
          <p class="muted or-sep">أو</p>
          <div class="field"><label for="ru">ضع رابطًا (Google Drive، OneDrive، YouTube، Canva)</label><input id="ru" type="url" dir="ltr" placeholder="https://"></div>
        </div>
        <label class="check" style="margin-bottom:16px"><input type="checkbox" id="rpub"> متاحة للزوار دون تسجيل دخول</label>
        <p class="form-error" id="rerr"></p>
        <div class="dialog-actions"><button class="btn btn-primary" id="rsave" value="save">حفظ المادة</button><button class="btn btn-ghost" value="cancel" formnovalidate>إلغاء</button></div>
      </form>
    </dialog>`);

    document.getElementById("filters").onsubmit = (e) => {
      e.preventDefault();
      location.hash = `#/admin?subject=${document.getElementById("fs").value}&year=${document.getElementById("fy").value}&track=${document.getElementById("ft").value}`;
    };
    main.querySelectorAll("[data-read]").forEach((b) => b.addEventListener("click", async () => {
      const { error: e } = await sb.from("contact_messages").update({ is_read: true }).eq("id", b.dataset.read);
      if (e) toast("تعذّر الحفظ: " + e.message); else { b.closest(".msg").classList.remove("unread"); b.remove(); toast("عُلّمت كمقروءة"); }
    }));
    main.querySelectorAll("[data-pub]").forEach((cb) => cb.addEventListener("change", async () => {
      const { error: e } = await sb.from("lessons").update({ is_published: cb.checked }).eq("id", cb.dataset.pub);
      if (e) { cb.checked = !cb.checked; toast("تعذّر الحفظ: " + e.message); } else toast(cb.checked ? "نُشر الدرس" : "أُخفي الدرس");
    }));
    main.querySelectorAll("[data-del]").forEach((b) => b.addEventListener("click", async () => {
      if (!confirm("حذف هذه المادة من الدرس؟")) return;
      const { data: rr } = await sb.from("lesson_resources").select("storage_path").eq("id", b.dataset.del).maybeSingle();
      const { error: e } = await sb.from("lesson_resources").delete().eq("id", b.dataset.del);
      if (!e && rr && rr.storage_path) await sb.storage.from(FILE_BUCKET).remove([rr.storage_path]);
      if (e) toast("تعذّر الحذف: " + e.message); else { toast("حُذفت المادة"); pageAdmin(params); }
    }));
    const dlg = document.getElementById("resDialog");
    let current = null;
    main.querySelectorAll("[data-add]").forEach((b) => b.addEventListener("click", () => {
      current = b.dataset.add;
      document.getElementById("resTitle").textContent = "إضافة مادة: " + b.dataset.title;
      document.getElementById("resForm").reset();
      document.getElementById("rerr").textContent = "";
      const ra = document.getElementById("ra"), rpub = document.getElementById("rpub");
      ra.onchange = () => { rpub.disabled = ra.value === "teacher"; if (rpub.disabled) rpub.checked = false; };
      ra.onchange();
      state._dropFile = null; state._dropFiles = null; document.getElementById("rk").dataset.touched = ""; document.getElementById("rfName").textContent = "أو اسحب الملفات وأفلتها هنا";
      const dz = document.getElementById("dropZone"), rf = document.getElementById("rf");
      const rkEl = document.getElementById("rk"); if (!rkEl.dataset.w) { rkEl.dataset.w = 1; rkEl.addEventListener("change", () => { rkEl.dataset.touched = "1"; }); }
      const guessKind = (n) => { if (document.getElementById("rk").dataset.touched) return; const m0 = autoMeta(n); document.getElementById("rk").value = m0.kind; return;
        const x = extOf(n); document.getElementById("rk").value = ["ppt", "pptx"].includes(x) ? "slides" : ["mp4"].includes(x) ? "video" : ["mp3", "m4a"].includes(x) ? "audio" : ["doc", "docx", "pdf"].includes(x) ? (document.getElementById("rk").value === "slides" && x === "pdf" ? "slides" : "worksheet") : "file"; };
      const showFiles = (fs) => { const n = document.getElementById("rfName"); if (fs.length === 1) { n.textContent = fs[0].name; guessKind(fs[0].name); document.getElementById("rt").disabled = false; }
        else { n.innerHTML = `<b>${fs.length} ملفات</b>: ` + fs.map((f) => esc(f.name)).join("، ") + '<br><span class="muted">يُعطى كل ملف عنوانًا ونوعًا تلقائيًا من اسمه.</span>'; document.getElementById("rt").disabled = true; } };
      rf.onchange = () => { state._dropFile = null; state._dropFiles = rf.files.length > 1 ? [...rf.files] : null; if (rf.files.length) showFiles([...rf.files]); };
      dz.ondragover = (ev) => { ev.preventDefault(); dz.classList.add("over"); };
      dz.ondragleave = () => dz.classList.remove("over");
      dz.ondrop = (ev) => { ev.preventDefault(); dz.classList.remove("over"); const fs = [...ev.dataTransfer.files]; if (!fs.length) return;
        if (fs.length === 1) { state._dropFile = fs[0]; state._dropFiles = null; } else { state._dropFile = null; state._dropFiles = fs; } showFiles(fs); };
      dlg.showModal();
    }));
    // smart title and kind from a file name: "Y11_U1_L3_The_Mind_in_Islam_Part1.pptx" -> "The Mind in Islam · Part 1"
    const autoMeta = (name) => {
      const ext = extOf(name);
      let t = name.replace(/\.[^.]+$/, "").replace(/^(Y|G|Grade|Year)\s?\d+[_\- ]*/i, "").replace(/^U\d+[_\- ]*/i, "").replace(/^L\d+[_\- ]*/i, "")
        .replace(/[_]+/g, " ").replace(/\s*-\s*/g, " - ").replace(/Part\s?(\d+)/i, "· Part $1").replace(/\s+/g, " ").trim();
      const low = name.toLowerCase();
      let kind = ["ppt", "pptx"].includes(ext) ? "slides" : ext === "mp4" ? "video" : ["mp3", "m4a"].includes(ext) ? "audio" : ["doc", "docx", "pdf"].includes(ext) ? "worksheet" : "file";
      if (/(^|[^a-z])ws([^a-z]|$)|worksheet|ورقة/.test(low)) { kind = "worksheet"; if (/^ws$/i.test(t) || !t) t = "Worksheet"; else t = t.replace(/^WS\b/i, "Worksheet"); }
      if (/group|task|مجموع/.test(low)) kind = "worksheet";
      if (/source|مصدر|مصادر|reading/.test(low)) kind = "file";
      if (/^ws$/i.test(t)) t = "Worksheet";
      let aud = null;
      if (kind === "slides" || (ext === "pdf" && /slide|شرائح|summary|ملخص/.test(low))) { kind = "slides"; aud = /student|summary|summ|ملخص|طالب|revision|مراجعة/.test(low) ? "student" : "teacher"; }
      return { title: t || name, kind, aud };
    };
    document.getElementById("rsave").addEventListener("click", async (e) => {
      e.preventDefault();
      if (state._dropFiles && state._dropFiles.length > 1) {
        const rerr = document.getElementById("rerr"), btn = document.getElementById("rsave");
        const big = state._dropFiles.filter((f) => f.size > 52428800);
        if (big.length) { rerr.textContent = "ملفات أكبر من 50 ميغابايت: " + big.map((f) => f.name).join("، "); return; }
        btn.disabled = true; const audSel = document.getElementById("ra").value, part = document.getElementById("rp").value; let ok = 0;
        for (const [k, f] of state._dropFiles.entries()) {
          btn.textContent = `جارٍ رفع ${k + 1} من ${state._dropFiles.length}…`;
          const m = autoMeta(f.name); if (document.getElementById("rk").dataset.touched) { m.kind = document.getElementById("rk").value; if (m.kind !== "slides") m.aud = null; }
          const aud = audSel === "auto" ? (m.aud || (m.kind === "slides" ? "teacher" : "student")) : audSel;
          const safe = f.name.toLowerCase().replace(/[^a-z0-9.\-_]/g, "-").replace(/-+/g, "-");
          const path = `${current}/${Date.now()}-${k}-${safe}`;
          const up = await sb.storage.from(FILE_BUCKET).upload(path, f, { contentType: f.type || undefined, upsert: false });
          if (up.error) { rerr.textContent = `تعذّر رفع ${f.name}: ${up.error.message}`; continue; }
          const ins = await sb.from("lesson_resources").insert({ lesson_id: current, kind: m.kind, part: part ? Number(part) : null, title_ar: m.title, url: null, storage_path: path, audience: aud,
            is_public: aud !== "teacher" && document.getElementById("rpub").checked, sort_order: k });
          if (ins.error) { rerr.textContent = `تعذّر حفظ ${f.name}: ${ins.error.message}`; continue; }
          ok++;
        }
        btn.disabled = false; btn.textContent = "حفظ المادة";
        if (ok === state._dropFiles.length) { dlg.close(); toast(`رُفعت ${ok} ملفات`); pageAdmin(params); } else toast(`رُفع ${ok} من ${state._dropFiles.length}`);
        return;
      }
      const url = document.getElementById("ru").value.trim();
      const file = state._dropFile || (document.getElementById("rf").files || [])[0];
      let title = document.getElementById("rt").value.trim();
      if (!title && file) title = file.name.replace(/\.[^.]+$/, "");
      const rerr = document.getElementById("rerr");
      if (!title) { rerr.textContent = "اكتب عنوانًا للمادة."; return; }
      if (!file && !/^https:\/\//.test(url)) { rerr.textContent = "ارفع ملفًا أو ضع رابطًا يبدأ بـ https://"; return; }
      if (file && file.size > 52428800) { rerr.textContent = "حجم الملف أكبر من 50 ميغابايت."; return; }
      let storage_path = null;
      if (file) {
        const btn = document.getElementById("rsave"); btn.disabled = true; btn.textContent = "جارٍ الرفع…";
        const safe = file.name.toLowerCase().replace(/[^a-z0-9.\-_]/g, "-").replace(/-+/g, "-");
        storage_path = `${current}/${Date.now()}-${safe}`;
        const up = await sb.storage.from(FILE_BUCKET).upload(storage_path, file, { contentType: file.type || undefined, upsert: false });
        btn.disabled = false; btn.textContent = "حفظ المادة";
        if (up.error) { rerr.textContent = "تعذّر رفع الملف: " + up.error.message; return; }
      }
      const part = document.getElementById("rp").value;
      const { error: e2 } = await sb.from("lesson_resources").insert({
        lesson_id: current, kind: document.getElementById("rk").value, part: part ? Number(part) : null,
        title_ar: title, url: file ? null : url, storage_path,
        audience: document.getElementById("ra").value === "auto" ? (document.getElementById("rk").value === "slides" ? (((state._dropFile || (document.getElementById("rf") && document.getElementById("rf").files[0])) && autoMeta((state._dropFile || document.getElementById("rf").files[0]).name).aud) || "teacher") : "student") : document.getElementById("ra").value,
        is_public: !["teacher", "auto"].includes(document.getElementById("ra").value) && document.getElementById("rpub").checked
      });
      if (e2) { document.getElementById("rerr").textContent = "تعذّر الحفظ: " + e2.message; return; }
      dlg.close(); toast("حُفظت المادة"); pageAdmin(params);
    });
  }

  function pageAbout() {
    setNav("about");
    h(`<section class="page-head"><div class="wrap" style="padding-bottom:34px">
        <div class="crumbs"><a href="#/">الرئيسية</a></div><h1>عن حراء</h1></div></section>
      <section class="section"><div class="wrap prose">
        <p>في غار حراء نزلت أول كلمة من الوحي: «اقرأ». ومن هنا جاء اسم المنصة: مكان يبدأ منه الطالب القراءة والفهم، ثم يصعد درجة بعد درجة.</p>
        <h2>كيف تعمل</h2>
        <p>تضم حراء ثلاث مواد: التربية الإسلامية، واللغة العربية، والدراسات الاجتماعية. كل صف مقسّم على الفصول الدراسية الثلاثة كما في كتب وزارة التربية والتعليم، وكل درس مربوط بنواتج التعلم في الإطار الوطني لمعايير مادته بأرقامها.</p>
        <p>في بداية كل فصل يؤدي الطالب اختبارًا تشخيصيًا، كل سؤال فيه يقيس ناتجًا محددًا. فتظهر خريطة إتقانه: ما أتقنه، وما يقترب منه، وما يحتاج إلى علاج، مع الدرس الذي يعالجه. وفي نهاية الفصل يقاس التقدم بالمقارنة مع نتيجته الأولى.</p>
        <h2>مساران</h2>
        <p>في كل مادة مسار للناطقين بالعربية ومسار لغير الناطقين، بكتاب كل منهما. والمساران يقاسان على نواتج التعلم نفسها.</p>
        <h2>القرآن والسنة</h2>
        <p>الآيات والأحاديث المقررة تُعرض مع مصدرها. ولا يُوسم الحديث بأنه «موثّق» إلا بعد مراجعة لفظه وتخريجه في مصادره.</p>
      </div></section>`);
  }

  function pageContact() {
    setNav("contact");
    const ROLES = { teacher: "معلم", parent: "ولي أمر", school: "إدارة مدرسة", student: "طالب", other: "أخرى" };
    h(`<section class="page-head"><div class="wrap" style="padding-bottom:34px">
        <div class="crumbs"><a href="#/">الرئيسية</a></div>
        <h1>تواصل معنا</h1>
        <p class="muted">لاستفسار، أو اقتراح، أو طلب ضم مدرستك إلى حراء، اكتب رسالتك وسنرد عليك في أقرب وقت.</p>
      </div></section>
      <section class="section" style="padding-top:40px"><div class="wrap">
        <div class="contact-direct">
          <a class="contact-item" href="tel:+971566460831">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M5 4h4l2 5-2.5 1.5a11 11 0 0 0 5 5L15 13l5 2v4a2 2 0 0 1-2 2A16 16 0 0 1 3 6a2 2 0 0 1 2-2"/></svg>
            <span><span class="ci-label">الهاتف</span><span class="ci-value" dir="ltr">056 646 0831</span></span></a>
          <a class="contact-item" href="https://wa.me/971566460831" target="_blank" rel="noopener">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M4 20l1.3-4A8 8 0 1 1 8 19z"/><path d="M9 9.5c.5 2 2.5 4 4.5 4.5l1-1.2 2 .8-.4 1.6c-3.5.2-7.6-3.9-7.4-7.4l1.6-.4.8 2z"/></svg>
            <span><span class="ci-label">واتساب</span><span class="ci-value" dir="ltr">056 646 0831</span></span></a>
          <a class="contact-item" href="mailto:abobakr789@gmail.com">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 7l9 6 9-6"/></svg>
            <span><span class="ci-label">البريد الإلكتروني</span><span class="ci-value" dir="ltr">abobakr789@gmail.com</span></span></a>
        </div>
        <p class="contact-or muted">أو اترك لنا رسالة من هنا:</p>
        <form class="form-card contact-card" id="contactForm" novalidate>
          <div class="field"><label for="cn">الاسم</label><input id="cn" autocomplete="name" required maxlength="120"></div>
          <div class="field"><label for="cc">البريد الإلكتروني أو رقم الهاتف</label><input id="cc" dir="ltr" autocomplete="email" required maxlength="160"></div>
          <div class="field"><label for="cr">أنت</label><select id="cr">${Object.keys(ROLES).map((k) => `<option value="${k}">${ROLES[k]}</option>`).join("")}</select></div>
          <div class="field"><label for="cm">رسالتك</label><textarea id="cm" rows="6" required maxlength="3000"></textarea></div>
          <div class="hp" aria-hidden="true"><label for="cw">لا تملأ هذا الحقل</label><input id="cw" tabindex="-1" autocomplete="off"></div>
          <p class="form-error" id="cerr"></p>
          <button class="btn btn-primary" type="submit" id="csend" style="width:100%">إرسال الرسالة</button>
        </form>
      </div></section>`);
    const form = document.getElementById("contactForm"), err = document.getElementById("cerr"), btn = document.getElementById("csend");
    form.onsubmit = async (e) => {
      e.preventDefault();
      if (document.getElementById("cw").value) return;
      const name = document.getElementById("cn").value.trim(), contact = document.getElementById("cc").value.trim();
      const message = document.getElementById("cm").value.trim(), sender_role = document.getElementById("cr").value;
      if (name.length < 2) { err.textContent = "اكتب اسمك."; return; }
      if (contact.length < 5) { err.textContent = "اكتب بريدك الإلكتروني أو رقم هاتفك لنتمكن من الرد عليك."; return; }
      if (message.length < 5) { err.textContent = "اكتب رسالتك."; return; }
      btn.disabled = true; err.textContent = "";
      const { error } = await sb.from("contact_messages").insert({ name, contact, sender_role, message });
      btn.disabled = false;
      if (error) { err.textContent = "تعذّر الإرسال، حاول مرة أخرى."; return; }
      form.outerHTML = '<div class="form-card contact-card empty"><strong>وصلتنا رسالتك، شكرًا لك</strong>سنتواصل معك قريبًا بإذن الله.</div>';
    };
  }

  async function pageTeacher(params) {
    setTimeout(maybeTour, 900);
    setNav("teacher");
    if (!state.session) { location.hash = "#/login"; return; }
    if (!isStaff()) { h('<div class="wrap loading">هذه الصفحة للمعلمين وإدارات المدارس.</div>'); return; }
    loading();
    const me = state.session.user.id, role = state.profile.role;
    const { data: allClasses, error } = await sb.from("classes")
      .select("id, name, year_group, track, subject_id, lock_lessons, academic_year, school_id, schools(name_ar), class_teachers(teacher_id)")
      .order("year_group").order("name");
    if (error) { h(`<div class="wrap loading">${esc(error.message)}</div>`); return; }
    const classes = role === "teacher" ? (allClasses || []).filter((c) => (c.class_teachers || []).some((t) => t.teacher_id === me)) : (allClasses || []);
    const canCreate = role === "super_admin" || role === "school_admin" || isHodAny();
    const clsId = params.get("class") || (classes[0] && classes[0].id);
    const cls = classes.find((c) => c.id === clsId);
    const term = ["1", "2", "3"].includes(params.get("term")) ? Number(params.get("term")) : 1;

    let schools = [];
    if (canCreate) { const r = await sb.from("schools").select("id, name_ar").order("name_ar"); schools = r.data || []; }
    const myClassesBySchool = {};
    (allClasses || []).forEach((c) => { (myClassesBySchool[c.school_id] = myClassesBySchool[c.school_id] || []).push(c); });
    const LETTERS = ["A", "B", "C", "D", "E", "F"];
    const createHtml = !canCreate ? "" : `<details class="msgs quick-setup" ${classes.length ? "" : "open"}><summary><strong>${classes.length ? "إضافة فصول" : "إعداد سريع: مدرستك وفصولك"}</strong></summary>
      <div class="qs-body">
        ${schools.length ? (schools.length > 1 ? `<div class="field"><label for="qsSchool">المدرسة</label><select id="qsSchool">${schools.map((x) => `<option value="${x.id}">${esc(x.name_ar)}</option>`).join("")}</select></div>`
            : `<input type="hidden" id="qsSchool" value="${schools[0].id}"><p class="qs-school">المدرسة: <strong>${esc(schools[0].name_ar)}</strong></p>`)
          : `<div class="field"><label for="qsNewSchool">اسم مدرستك</label><input id="qsNewSchool" placeholder="مثال: مدرسة النور الخاصة"></div>`}
        <p class="pref-label">1. اختر الصفوف</p>
        <div class="qs-grades">${Array.from({ length: 12 }, (_, i) => `<button type="button" class="qs-g" data-g="${i + 1}" aria-pressed="false">${i + 1}</button>`).join("")}</div>
        <div class="qs-row">
          <div><p class="pref-label">2. كم شعبة في كل صف؟</p>
            <div class="seg">${[1, 2, 3, 4, 5, 6].map((n) => `<button type="button" data-sec="${n}" aria-pressed="${n === 1}">${n}</button>`).join("")}</div></div>
          <div><p class="pref-label">3. المسار</p>
            <div class="seg"><button type="button" data-tr="native" aria-pressed="true">الناطقون بالعربية</button><button type="button" data-tr="non_native" aria-pressed="false">غير الناطقين</button><button type="button" data-tr="both" aria-pressed="false">كلاهما</button></div></div>
          <div><p class="pref-label">4. المادة</p>
            <div class="seg">${Object.keys(SUBJECTS).map((k, i) => `<button type="button" data-sub="${SUBJECTS[k].id}" aria-pressed="${i === 0}">${SUBJECTS[k].name}</button>`).join("")}</div></div>
        </div>
        <div class="qs-preview" id="qsPreview"><span class="muted">اختر صفًا واحدًا على الأقل.</span></div>
        <button class="btn btn-primary" id="qsGo" disabled>إنشاء الفصول</button>
      </div></details>`;

    let lessonsHtml = "";
    if (cls) {
      const [{ data: units }, { data: unl }] = await Promise.all([
        sb.from("units").select("id, term, sort_order, title_ar, lessons(id, code, sort_order, title_ar, title_en)")
          .eq("year_group", cls.year_group).eq("track", cls.track).eq("subject_id", cls.subject_id).eq("term", term).order("sort_order"),
        sb.from("class_lesson_unlocks").select("lesson_id, unlock_at").eq("class_id", cls.id)
      ]);
      const now = Date.now();
      const open = new Set((unl || []).filter((x) => new Date(x.unlock_at).getTime() <= now).map((x) => x.lesson_id));
      const sched = {}; (unl || []).forEach((x) => { if (new Date(x.unlock_at).getTime() > now) sched[x.lesson_id] = x.unlock_at; });
      const termLessons = (units || []).flatMap((u) => u.lessons || []);
      const { data: cs } = await sb.from("class_students").select("student_id, profiles(full_name_ar)").eq("class_id", cls.id);
      const roster = (cs || []).map((r) => ({ id: r.student_id, name: r.profiles ? r.profiles.full_name_ar : "" }));
      const rosterIds = new Set(roster.map((r) => r.id));
      let viewsBy = {};
      if (termLessons.length && roster.length) {
        const { data: vw } = await sb.from("lesson_views").select("lesson_id, student_id").in("lesson_id", termLessons.map((x) => x.id));
        (vw || []).forEach((v) => { if (rosterIds.has(v.student_id)) (viewsBy[v.lesson_id] = viewsBy[v.lesson_id] || new Set()).add(v.student_id); });
      }
      state._roster = roster; state._viewsBy = viewsBy;
      const dateVal = (iso) => { const d = new Date(iso); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`; };
      // ---- dashboard data ----
      const allUnl = (unl || []).slice().sort((x, y) => new Date(y.unlock_at) - new Date(x.unlock_at));
      const lastOpen = allUnl.find((x) => new Date(x.unlock_at).getTime() <= now);
      const nextSched = (unl || []).filter((x) => new Date(x.unlock_at).getTime() > now).sort((x, y) => new Date(x.unlock_at) - new Date(y.unlock_at))[0];
      const want = [lastOpen, nextSched].filter(Boolean).map((x) => x.lesson_id);
      const lessonInfo = {};
      if (want.length) { const { data: li } = await sb.from("lessons").select("id, code, title_ar").in("id", want); (li || []).forEach((x) => { lessonInfo[x.id] = x; }); }
      let todayViews = 0;
      if (lastOpen && roster.length) { const { data: tv } = await sb.from("lesson_views").select("student_id").eq("lesson_id", lastOpen.lesson_id); todayViews = (tv || []).filter((v) => rosterIds.has(v.student_id)).length; }
      const [{ data: dTests }, { data: dOpen }] = await Promise.all([
        sb.from("assessments").select("id, kind, term, title_ar").eq("year_group", cls.year_group).eq("subject_id", cls.subject_id).eq("track", cls.track).in("kind", ["diagnostic", "post"]).order("term"),
        sb.from("class_assessments").select("assessment_id").eq("class_id", cls.id)
      ]);
      const openT = new Set((dOpen || []).map((x) => x.assessment_id));
      const doneBy = {};
      if ((dTests || []).length && roster.length) {
        const { data: da } = await sb.from("attempts").select("assessment_id, student_id").in("assessment_id", dTests.map((t) => t.id)).not("submitted_at", "is", null);
        (da || []).forEach((x) => { if (rosterIds.has(x.student_id)) (doneBy[x.assessment_id] = doneBy[x.assessment_id] || new Set()).add(x.student_id); });
      }
      // exit tickets + recitations for this class
      const { data: tks } = termLessons.length ? await sb.from("assessments").select("id, lesson_id").eq("kind", "lesson_quiz").in("lesson_id", termLessons.map((x) => x.id)) : { data: [] };
      const tkBy = {}; (tks || []).forEach((t) => { tkBy[t.lesson_id] = t.id; });
      const tkStat = {};
      if ((tks || []).length && roster.length) {
        const { data: ta } = await sb.from("attempts").select("assessment_id, student_id, score, max_score, submitted_at").in("assessment_id", tks.map((t) => t.id)).not("submitted_at", "is", null);
        const last = {}; (ta || []).forEach((x) => { if (!rosterIds.has(x.student_id)) return; const k = x.assessment_id + "|" + x.student_id; if (!last[k] || last[k].submitted_at < x.submitted_at) last[k] = x; });
        Object.values(last).forEach((x) => { const s0 = tkStat[x.assessment_id] = tkStat[x.assessment_id] || { n: 0, sum: 0 }; s0.n++; s0.sum += x.max_score ? x.score / x.max_score : 0; });
      }
      let pendingRec = 0;
      if (roster.length) { const { count } = await sb.from("recitations").select("id", { count: "exact", head: true }).in("student_id", roster.map((r) => r.id)).eq("status", "submitted"); pendingRec = count || 0; }
      state._planUnits = units || [];
      const dash = `<div class="dash">
        <div class="dash-card">
          <h3>درس اليوم</h3>
          ${lastOpen && lessonInfo[lastOpen.lesson_id] ? `<a class="dash-big" href="#/lesson/${esc(lessonInfo[lastOpen.lesson_id].code)}">${esc(lessonInfo[lastOpen.lesson_id].title_ar)}</a>
            <p class="muted">${roster.length ? `فتحه ${todayViews} من ${roster.length}` : "لا يوجد طلاب في الفصل بعد"}</p>`
            : `<p class="muted">${cls.lock_lessons ? "لم تفتح أي درس بعد. افتح درسًا من القائمة بالأسفل." : "كل الدروس مفتوحة. فعّل القفل لتحدد درس اليوم."}</p>`}
          ${nextSched && lessonInfo[nextSched.lesson_id] ? `<p class="muted">التالي: ${esc(lessonInfo[nextSched.lesson_id].title_ar)} · ${new Date(nextSched.unlock_at).toLocaleDateString(LANG === "en" ? "en-GB" : "ar-AE", { weekday: "long", day: "numeric", month: "long" })}</p>` : ""}
        </div>
        <div class="dash-card">
          <h3>الاختبارات</h3>
          ${(dTests || []).length ? `<div class="dash-tests">${dTests.map((t) => `<div class="dt-row">
              <span>${t.kind === "post" ? "بعدي" : "تشخيصي"} ف${t.term}</span>
              <span class="muted">${roster.length ? `${doneBy[t.id] ? doneBy[t.id].size : 0}/${roster.length}` : ""}</span>
              <button class="btn btn-small ${openT.has(t.id) ? "btn-primary" : "btn-ghost"}" data-topen="${t.id}" data-on="${openT.has(t.id)}">${openT.has(t.id) ? "متاح" : "مغلق"}</button>
              <a class="btn btn-ghost btn-small" href="#/preview/${t.id}?class=${cls.id}">معاينة</a>
              <a class="btn btn-ghost btn-small" href="#/results?class=${cls.id}&test=${t.id}">النتائج</a></div>`).join("")}</div>`
            : '<p class="muted">لا توجد اختبارات لهذا الصف بعد.</p>'}
        </div>
        <div class="dash-card">
          <h3>الطلاب</h3>
          <p class="dash-big">${roster.length}</p>
          ${isSchoolAdmin() ? `<a class="btn btn-ghost btn-small" href="#/manage?school=${cls.school_id}&tab=students&class=${cls.id}">إضافة طلاب وطباعة البطاقات</a>` : ""}
          <h3 style="margin-top:14px">حصة اليوم</h3>
          <button class="btn btn-primary btn-small" data-today="${cls.id}">ابدأ حصة اليوم أو جدول الدروس</button>
          <h3 style="margin-top:14px">سجل الدرجات</h3>
          <a class="btn btn-dawn btn-small" href="#/gradebook?class=${cls.id}">سجل الدرجات والتحليل</a> <a class="btn btn-ghost btn-small" href="#/evidence?class=${cls.id}">📑 ملف أدلة التفتيش</a> <a class="btn btn-ghost btn-small" href="#/inspection?subject=${({ 1: "islamic", 2: "arabic", 3: "social" })[cls.subject_id] || "islamic"}">📊 تقرير المدرسة</a>
          <h3 style="margin-top:14px">الواجبات</h3>
          <a class="btn btn-ghost btn-small" href="#/homework?class=${cls.id}">واجبات الفصل</a>
          <h3 style="margin-top:14px">أذونات المحتوى</h3>
          <a class="btn btn-ghost btn-small" href="#/access">طلبات الوصول</a>
          <h3 style="margin-top:14px">التسميع</h3>
          <a class="btn ${pendingRec ? "btn-dawn" : "btn-ghost"} btn-small" href="#/recitations?class=${cls.id}">${pendingRec ? `${pendingRec} بانتظار التقييم` : "لا تسميعات جديدة"}</a>
        </div>
      </div>`;
      lessonsHtml = dash + `
        <h2 style="margin:34px 0 14px">الدروس</h2>
        <div class="lock-mode ${cls.lock_lessons ? "on" : ""}">
          <label class="switch"><input type="checkbox" id="lockMode" ${cls.lock_lessons ? "checked" : ""}><span></span></label>
          <div><strong>${cls.lock_lessons ? "القفل مفعّل: الطلاب يرون الدروس التي تفتحها فقط" : "القفل متوقف: كل الدروس مفتوحة للطلاب"}</strong>
          <p class="muted">${cls.lock_lessons ? "عناوين الدروس تبقى ظاهرة، لكن شرائح الطالب وأوراق العمل والفيديو والاختبار لا تُفتح إلا للدروس المفتوحة." : "فعّل القفل لتتحكم في الدروس التي يصل إليها طلاب هذا الفصل."}</p></div>
        </div>
        <div class="controls" style="margin:22px 0 10px">
          <div class="term-tabs" role="tablist">${[1, 2, 3].map((t) => `<a class="term-tab" role="tab" style="text-decoration:none" href="#/teacher?class=${cls.id}&term=${t}" aria-selected="${t === term}">${TERMS[t]}</a>`).join("")}</div>
          <div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn btn-dawn btn-small" id="planTerm">تخطيط الفصل الدراسي تلقائيًا</button><button class="btn btn-ghost btn-small" id="openAll">فتح كل دروس الفصل الدراسي</button><button class="btn btn-ghost btn-small" id="lockAll">قفل الكل</button></div>
        </div>
        ${(units || []).length ? (units || []).map((u) => `<div class="unit"><div class="unit-head"><h2>${esc(u.title_ar)}</h2></div>
          ${(u.lessons || []).sort((a, b) => a.sort_order - b.sort_order).map((l, i) => {
            const isOpen = open.has(l.id), when = sched[l.id];
            const seen = viewsBy[l.id] ? viewsBy[l.id].size : 0;
            return `<div class="lesson-row t-row ${isOpen ? "" : "locked"}"><span class="idx">${i + 1}</span>
              <span><a class="t" href="#/lesson/${esc(l.code)}">${esc(l.title_ar)}</a>
                ${when ? `<span class="pill warn sched-pill">يُفتح تلقائيًا ${new Date(when).toLocaleDateString(LANG === "en" ? "en-GB" : "ar-AE", { weekday: "long", day: "numeric", month: "long" })}</span>` : ""}</span>
              <span class="meta t-meta">
                ${roster.length ? `<button class="btn btn-ghost btn-small" data-views="${l.id}" title="من فتح الدرس">${seen}/${roster.length} فتحوه</button>` : ""}
                ${tkBy[l.id] && tkStat[tkBy[l.id]] ? `<a class="btn btn-ghost btn-small" href="#/results?class=${cls.id}&test=${tkBy[l.id]}" title="نتائج بطاقة الخروج">بطاقة الخروج ${tkStat[tkBy[l.id]].n}/${roster.length} · ${Math.round((tkStat[tkBy[l.id]].sum / tkStat[tkBy[l.id]].n) * 100)}%</a>` : ""}
                ${isOpen ? "" : `<label class="sched" title="فتح تلقائي في تاريخ"><span class="sr">فتح تلقائي في</span><input type="date" data-sched="${l.id}" value="${when ? dateVal(when) : ""}"></label>`}
                <button class="btn btn-small ${isOpen ? "btn-primary" : "btn-ghost"}" data-toggle="${l.id}" data-open="${isOpen}">
                ${isOpen ? unlockIcon + " مفتوح" : lockIcon + " مقفل"}</button></span></div>`;
          }).join("")}</div>`).join("") : `<div class="empty"><strong>لا توجد دروس لهذا الصف والمسار في ${TERMS[term]}</strong></div>`}`;
      state._termLessonIds = termLessons.map((x) => x.id);
      state._guide = { students: roster.length > 0, tests: openT.size > 0, lesson: !cls.lock_lessons || (unl || []).length > 0, cls };
    }

    h(`<section class="page-head"><div class="wrap" style="padding-bottom:30px">
        <div class="crumbs">فصولي</div>
        <h1>لوحة الفصل</h1>
        <p class="muted" style="margin:0">درس اليوم، والاختبارات، والطلاب، وقفل الدروس، في مكان واحد.</p>
         <p style="margin:10px 0 0"><a class="btn btn-small btn-primary" href="#/inspection">📊 تقرير التفتيش للمدرسة</a>${isSuper() ? ` <a class="btn btn-small btn-ghost" href="#/reports">🛠️ بلاغات المحتوى</a>` : ""}</p>

      </div></section>
      <section class="section" style="padding-top:34px"><div class="wrap">
        ${(() => {
          let done = false; try { done = localStorage.getItem("hira-guide-done") === "1"; } catch (e) {}
          const g = state._guide && cls && state._guide.cls === cls ? state._guide : { students: false, tests: false, lesson: false };
          const steps = [
            [classes.length > 0, "أنشئ فصولك", canCreate ? "من «الإعداد السريع» بالأسفل: اختر الصفوف وعدد الشعب" : "تطلبه من إدارة المدرسة", null],
            [g.students, "أضف الطلاب واطبع بطاقات دخولهم", "من «إدارة المدرسة» ← الطلاب", cls && isSchoolAdmin() ? `#/manage?school=${cls.school_id}&tab=students&class=${cls.id}` : null],
            [g.tests, "أتح الاختبار التشخيصي للفصل الأول", "من بطاقة «الاختبارات» بالأسفل", null],
            [g.lesson, "افتح درس اليوم", "فعّل القفل وافتح الدرس من قائمة «الدروس»", null]
          ];
          const n = steps.filter((x) => x[0]).length;
          if (done || n === steps.length) return "";
          return `<div class="guide"><div class="guide-head"><strong>ابدأ هنا</strong><span class="muted">${n} من ${steps.length} خطوات</span>
              <button class="btn btn-ghost btn-small" id="hideGuide">إخفاء</button></div>
            <div class="guide-bar"><span style="width:${Math.round((n / steps.length) * 100)}%"></span></div>
            <ol class="guide-steps">${steps.map(([ok, t, hint, link]) => `<li class="${ok ? "ok" : ""}"><span class="tick">${ok ? "✓" : ""}</span>
              <span>${link && !ok ? `<a href="${link}">${t}</a>` : t}<small class="muted">${ok ? "تمّت" : hint}</small></span></li>`).join("")}</ol></div>`;
        })()}
        ${params.get("setup") || !classes.length ? createHtml : canCreate ? `<p class="muted small" style="margin:0 0 14px">🏫 ${CT("إضافة الفصول وتعديلها من", "Add or edit classes from")} <a href="#/teacher?setup=1">${CT("إدارة الفصول", "class management")}</a></p>` : ""}
        ${classes.length ? `<div class="chips" style="margin-bottom:22px"><span class="chips-label">الفصل:</span>
          ${classes.map((c) => `<a class="chip" href="#/teacher?class=${c.id}" aria-current="${cls && c.id === cls.id}">${esc(c.name)} · Grade ${c.year_group} · ${c.track === "non_native" ? CT("غير الناطقين", "Non-Arabic speakers") : CT("الناطقون", "Arabic speakers")}${role !== "teacher" && c.schools ? ` · ${esc(c.schools.name_ar)}` : ""}</a>`).join("")}</div>`
          : `<div class="empty"><strong>لا توجد فصول ${role === "teacher" ? "مسندة إليك" : ""} بعد</strong>${role === "teacher" ? "حسابك جاهز. تُسند لك إدارة المدرسة فصولك من «إدارة المدرسة» ← المعلمون، وتظهر هنا مباشرة. وإلى ذلك الحين تستطيع تصفّح كل الدروس من «الصفوف»." : "أنشئ أول فصل من الأعلى."}</div>`}
        ${lessonsHtml}
      </div></section>`);

    const hg = document.getElementById("hideGuide");
    if (hg) hg.onclick = () => { try { localStorage.setItem("hira-guide-done", "1"); } catch (e) {} hg.closest(".guide").remove(); };
    const qs = { grades: new Set(), sec: 1, tr: "native", sub: SUBJECTS[Object.keys(SUBJECTS)[0]].id };
    const qsPlan = () => {
      const tracks = qs.tr === "both" ? ["native", "non_native"] : [qs.tr];
      const sid = (document.getElementById("qsSchool") || {}).value;
      const existing = new Set(((sid && myClassesBySchool[sid]) || []).map((c) => `${c.name}|${c.track}|${c.subject_id}`));
      const out = [];
      [...qs.grades].sort((a, b) => a - b).forEach((g) => tracks.forEach((t) => LETTERS.slice(0, qs.sec).forEach((L) => {
        const name = qs.sec === 1 ? `${g}` + "A" : `${g}${L}`;
        if (qs.sec === 1 && L !== "A") return;
        out.push({ name, year_group: g, track: t, subject_id: qs.sub, dup: existing.has(`${name}|${t}|${qs.sub}`) });
      })));
      return out;
    };
    const qsDraw = () => {
      const pv = document.getElementById("qsPreview"), go = document.getElementById("qsGo");
      if (!pv) return;
      const plan = qsPlan(), fresh = plan.filter((x) => !x.dup);
      pv.innerHTML = plan.length ? plan.map((x) => `<span class="chip ${x.dup ? "dup" : ""}" title="${x.dup ? "موجود مسبقًا" : ""}">${esc(x.name)}${qs.tr === "both" ? ` · ${x.track === "native" ? "ناطقون" : "غير ناطقين"}` : ""}</span>`).join("")
        : '<span class="muted">اختر صفًا واحدًا على الأقل.</span>';
      go.disabled = !fresh.length;
      go.textContent = fresh.length ? `إنشاء ${fresh.length} ${fresh.length === 1 ? "فصل" : fresh.length <= 10 ? "فصول" : "فصلًا"}` : "إنشاء الفصول";
    };
    main.querySelectorAll(".qs-g").forEach((b) => b.onclick = () => { const g = Number(b.dataset.g); qs.grades.has(g) ? qs.grades.delete(g) : qs.grades.add(g); b.setAttribute("aria-pressed", String(qs.grades.has(g))); qsDraw(); });
    const segPick = (attr, key, cast) => main.querySelectorAll(`[${attr}]`).forEach((b) => b.onclick = () => {
      qs[key] = cast(b.getAttribute(attr)); main.querySelectorAll(`[${attr}]`).forEach((x) => x.setAttribute("aria-pressed", String(x === b))); qsDraw(); });
    segPick("data-sec", "sec", Number); segPick("data-tr", "tr", String); segPick("data-sub", "sub", Number);
    const qsSel = document.getElementById("qsSchool"); if (qsSel && qsSel.tagName === "SELECT") qsSel.onchange = qsDraw;
    const qsGo = document.getElementById("qsGo");
    if (qsGo) qsGo.onclick = async () => {
      qsGo.disabled = true; qsGo.textContent = "جارٍ الإنشاء…";
      let schoolId = (document.getElementById("qsSchool") || {}).value;
      if (!schoolId) {
        const name = (document.getElementById("qsNewSchool").value || "").trim();
        if (name.length < 3) { toast("اكتب اسم المدرسة"); qsDraw(); return; }
        const latin = name.toLowerCase().replace(/[^a-z0-9\s-]/g, "").trim().replace(/\s+/g, "-").slice(0, 24);
        let made = null;
        for (let k = 0; k < 4 && !made; k++) {
          const code = (latin.length >= 3 && k === 0) ? latin : `school-${Math.floor(1000 + Math.random() * 9000)}`;
          const r = await sb.from("schools").insert({ name_ar: name, code }).select("id").single();
          if (!r.error) made = r.data.id; else if (!/duplicate|unique/i.test(r.error.message)) { toast("تعذّر إنشاء المدرسة: " + r.error.message); qsDraw(); return; }
        }
        schoolId = made;
      }
      const rows = qsPlan().filter((x) => !x.dup).map((x) => ({ school_id: schoolId, name: x.name, year_group: x.year_group, track: x.track, subject_id: x.subject_id, academic_year: "2025-2026" }));
      const r2 = await sb.from("classes").insert(rows).select("id");
      if (r2.error) { toast("تعذّر إنشاء الفصول: " + r2.error.message); qsDraw(); return; }
      toast(`أُنشئ ${rows.length} ${rows.length === 1 ? "فصل" : "فصول"}`);
      location.hash = "#/teacher?class=" + r2.data[0].id;
    };
    qsDraw();
    if (!cls) return;
    const reload = () => pageTeacher(params);
    document.getElementById("lockMode").onchange = async (e) => {
      const { error: e1 } = await sb.from("classes").update({ lock_lessons: e.target.checked }).eq("id", cls.id);
      if (e1) { toast("تعذّر الحفظ: " + e1.message); e.target.checked = !e.target.checked; return; }
      toast(e.target.checked ? "فُعّل القفل" : "أُوقف القفل"); reload();
    };
    main.querySelectorAll("[data-toggle]").forEach((b) => b.addEventListener("click", async () => {
      b.disabled = true;
      const isOpen = b.dataset.open === "true";
      const r = isOpen
        ? await sb.from("class_lesson_unlocks").delete().eq("class_id", cls.id).eq("lesson_id", b.dataset.toggle)
        : await sb.from("class_lesson_unlocks").upsert({ class_id: cls.id, lesson_id: b.dataset.toggle, unlocked_by: me, unlock_at: new Date().toISOString() }, { onConflict: "class_id,lesson_id" });
      if (r.error) { toast("تعذّر الحفظ: " + r.error.message); b.disabled = false; return; }
      reload();
    }));
    main.querySelectorAll("[data-sched]").forEach((inp) => inp.addEventListener("change", async () => {
      const lessonId = inp.dataset.sched;
      const r = inp.value
        ? await sb.from("class_lesson_unlocks").upsert({ class_id: cls.id, lesson_id: lessonId, unlocked_by: me, unlock_at: new Date(inp.value + "T06:00:00").toISOString() }, { onConflict: "class_id,lesson_id" })
        : await sb.from("class_lesson_unlocks").delete().eq("class_id", cls.id).eq("lesson_id", lessonId);
      if (r.error) toast("تعذّر الحفظ: " + r.error.message); else { toast(inp.value ? "سيُفتح الدرس تلقائيًا صباح " + inp.value : "أُلغي الفتح التلقائي"); reload(); }
    }));
    main.querySelectorAll("[data-views]").forEach((b) => b.addEventListener("click", () => {
      const seen = state._viewsBy[b.dataset.views] || new Set();
      const yes = state._roster.filter((r) => seen.has(r.id)), no = state._roster.filter((r) => !seen.has(r.id));
      let d = document.getElementById("viewsDlg");
      if (!d) { d = document.createElement("dialog"); d.id = "viewsDlg"; document.body.appendChild(d); }
      d.innerHTML = `<h2 style="font-size:1.2rem">متابعة فتح الدرس</h2>
        <h3 class="res-group">لم يفتحوه بعد (${no.length})</h3><p>${no.map((r) => esc(r.name)).join("، ") || "لا أحد"}</p>
        <h3 class="res-group">فتحوه (${yes.length})</h3><p class="muted">${yes.map((r) => esc(r.name)).join("، ") || "لا أحد بعد"}</p>
        <div class="dialog-actions"><button class="btn btn-ghost" id="closeViews">إغلاق</button></div>`;
      d.showModal(); document.getElementById("closeViews").onclick = () => d.close();
    }));
    main.querySelectorAll("[data-topen]").forEach((b) => b.addEventListener("click", async () => {
      b.disabled = true;
      const on = b.dataset.on === "true";
      const r = on ? await sb.from("class_assessments").delete().eq("class_id", cls.id).eq("assessment_id", b.dataset.topen)
                   : await sb.from("class_assessments").insert({ class_id: cls.id, assessment_id: b.dataset.topen, opened_by: me });
      if (r.error) { toast("تعذّر الحفظ: " + r.error.message); b.disabled = false; return; }
      toast(on ? "أُغلق الاختبار" : "أُتيح الاختبار للطلاب"); reload();
    }));
    document.getElementById("planTerm").onclick = () => {
      let d = document.getElementById("planDlg");
      if (!d) { d = document.createElement("dialog"); d.id = "planDlg"; d.className = "wide-dlg"; document.body.appendChild(d); }
      const DAYS = [[1, "الإثنين"], [2, "الثلاثاء"], [3, "الأربعاء"], [4, "الخميس"], [5, "الجمعة"], [6, "السبت"], [0, "الأحد"]];
      const today = new Date(); const iso = (x) => `${x.getFullYear()}-${String(x.getMonth() + 1).padStart(2, "0")}-${String(x.getDate()).padStart(2, "0")}`;
      d.innerHTML = `<h2 style="font-size:1.25rem">تخطيط ${TERMS[term]} تلقائيًا</h2>
        <p class="muted">أدخل أيام حصصك وتاريخ البداية، فتُجدول المنصة فتح دروس هذا الفصل الدراسي بالترتيب، وتتخطى الإجازات.</p>
        <div class="admin-filters">
          <div class="field"><label for="pStart">تاريخ أول حصة</label><input id="pStart" type="date" value="${iso(today)}"></div>
          <div class="field"><label for="pPer">حصص لكل درس</label><select id="pPer"><option value="1">حصة واحدة</option><option value="2">حصتان</option><option value="3">ثلاث حصص</option></select></div>
        </div>
        <p class="pref-label">أيام الحصص</p>
        <div class="chk-grid" style="grid-template-columns:repeat(auto-fill,minmax(110px,1fr))">${DAYS.map(([v, n]) => `<label class="check"><input type="checkbox" class="pDay" value="${v}" ${[1, 3].includes(v) ? "checked" : ""}> ${n}</label>`).join("")}</div>
        <div class="field" style="margin-top:12px"><label for="pHol">الإجازات (كل إجازة في سطر: تاريخ البداية ثم تاريخ النهاية)</label>
          <textarea id="pHol" rows="3" dir="ltr" placeholder="2026-12-01 2026-12-03&#10;2027-01-01"></textarea></div>
        <button class="btn btn-ghost" id="pPreview">معاينة الجدول</button>
        <div id="pOut"></div>
        <div class="dialog-actions"><button class="btn btn-primary" id="pApply" disabled>اعتماد الجدول</button><button class="btn btn-ghost" id="pClose">إغلاق</button></div>`;
      d.showModal();
      d.querySelector("#pClose").onclick = () => d.close();
      let plan = [];
      d.querySelector("#pPreview").onclick = () => {
        const start = d.querySelector("#pStart").value, per = Number(d.querySelector("#pPer").value);
        const days = new Set([...d.querySelectorAll(".pDay:checked")].map((x) => Number(x.value)));
        if (!start || !days.size) { toast("اختر تاريخ البداية ويومًا واحدًا على الأقل"); return; }
        const hol = d.querySelector("#pHol").value.split(/\n/).map((x) => x.trim().split(/\s+/)).filter((x) => x[0]).map(([a, b]) => [a, b || a]);
        const isHol = (ds) => hol.some(([a, b]) => ds >= a && ds <= b);
        const lessons = state._planUnits.slice().sort((a, b) => a.sort_order - b.sort_order).flatMap((u) => (u.lessons || []).slice().sort((a, b) => a.sort_order - b.sort_order));
        plan = []; let dt = new Date(start + "T00:00:00"), guard = 0, sessions = 0, idx = 0;
        while (idx < lessons.length && guard++ < 800) {
          const ds = iso(dt);
          if (days.has(dt.getDay()) && !isHol(ds)) { if (sessions % per === 0) plan.push({ lesson: lessons[idx], date: ds }); sessions++; if (sessions % per === 0) idx++; }
          dt.setDate(dt.getDate() + 1);
        }
        d.querySelector("#pOut").innerHTML = `<div class="table-wrap" style="max-height:300px;overflow:auto;margin-top:12px"><table class="admin-table"><thead><tr><th>#</th><th>الدرس</th><th>يُفتح</th></tr></thead><tbody>
          ${plan.map((x, k) => `<tr><td>${k + 1}</td><td>${esc(x.lesson.title_ar)}</td><td>${new Date(x.date + "T06:00:00").toLocaleDateString(LANG === "en" ? "en-GB" : "ar-AE", { weekday: "long", day: "numeric", month: "long" })}</td></tr>`).join("")}</tbody></table></div>
          <p class="muted">آخر درس: ${plan.length ? new Date(plan[plan.length - 1].date + "T06:00:00").toLocaleDateString(LANG === "en" ? "en-GB" : "ar-AE", { day: "numeric", month: "long", year: "numeric" }) : ""}. سيُفعَّل القفل للفصل، والدروس المفتوحة حاليًا ستأخذ مواعيدها الجديدة.</p>`;
        d.querySelector("#pApply").disabled = !plan.length;
      };
      d.querySelector("#pApply").onclick = async () => {
        if (!plan.length) return;
        const rows = plan.map((x) => ({ class_id: cls.id, lesson_id: x.lesson.id, unlocked_by: me, unlock_at: new Date(x.date + "T06:00:00").toISOString() }));
        const r1 = await sb.from("class_lesson_unlocks").upsert(rows, { onConflict: "class_id,lesson_id" });
        if (r1.error) { toast("تعذّر الحفظ: " + r1.error.message); return; }
        if (!cls.lock_lessons) await sb.from("classes").update({ lock_lessons: true }).eq("id", cls.id);
        d.close(); toast(`جُدول ${plan.length} درسًا`); reload();
      };
    };
    document.getElementById("openAll").onclick = async () => {
      const ids = state._termLessonIds || [];
      if (!ids.length) return;
      const { error: e3 } = await sb.from("class_lesson_unlocks").upsert(ids.map((id) => ({ class_id: cls.id, lesson_id: id, unlocked_by: me, unlock_at: new Date().toISOString() })), { onConflict: "class_id,lesson_id" });
      if (e3) toast("تعذّر الحفظ: " + e3.message); else { toast("فُتحت كل الدروس"); reload(); }
    };
    document.getElementById("lockAll").onclick = async () => {
      const ids = state._termLessonIds || [];
      if (!ids.length || !confirm("قفل كل دروس هذا الفصل الدراسي؟")) return;
      const { error: e4 } = await sb.from("class_lesson_unlocks").delete().eq("class_id", cls.id).in("lesson_id", ids);
      if (e4) toast("تعذّر الحفظ: " + e4.message); else { toast("قُفلت الدروس"); reload(); }
    };
  }

  async function pageManage(params) {
    setNav("manage");
    if (!state.session) { location.hash = "#/login"; return; }
    const hod = !isSchoolAdmin() && isHodAny();
    if (!isSchoolAdmin() && !hod) { h('<div class="wrap loading">هذه الصفحة لإدارة المدرسة ورؤساء الأقسام.</div>'); return; }
    loading();
    const { data: schools } = await sb.from("schools").select("id, code, name_ar, teacher_invite").order("name_ar");
    const sid = params.get("school") || (isSuper() ? (schools[0] && schools[0].id) : state.profile.school_id);
    const school = (schools || []).find((x) => x.id === sid);
    const tab = params.get("tab") || "students";
    const base = (t, extra = "") => `#/manage?school=${sid || ""}&tab=${t}${extra}`;
    let body = "";
    if (!school) {
      body = `<div class="empty"><strong>لا توجد مدرسة بعد</strong>أنشئ أول مدرسة.</div>`;
    } else {
      const [{ data: classes }, { data: staff }] = await Promise.all([
        (hod ? sb.from("classes").select("id, name, year_group, track, subject_id").eq("school_id", sid).in("subject_id", hodSubs()) : sb.from("classes").select("id, name, year_group, track, subject_id").eq("school_id", sid)).order("year_group").order("name"),
        sb.from("profiles").select("id, full_name_ar, username, role, is_active, hod_subjects").eq("school_id", sid).in("role", ["teacher", "school_admin"]).order("full_name_ar")
      ]);
      const clsLabel = (c) => `${esc(c.name)} · Grade ${c.year_group} · ${SUBJECTS[SUBJECT_BY_ID[c.subject_id]].name} · ${TRACK_SHORT[c.track]}`;
      if (tab === "students") {
        const cid = params.get("class") || (classes[0] && classes[0].id);
        let list = "";
        if (cid) {
          const { data: st } = await sb.from("class_students").select("profiles(id, full_name_ar, username, is_active)").eq("class_id", cid);
          const studs = (st || []).map((r) => r.profiles).filter(Boolean).sort((a, b) => a.full_name_ar.localeCompare(b.full_name_ar, "ar"));
          state._famStuds = studs;
          list = `<div class="fam-cards-bar"><h3 style="margin:30px 0 0">طلاب الفصل (${studs.length})</h3>${studs.length ? '<button class="btn btn-dawn btn-small" id="famCards">👨‍👩‍👧 بطاقات ربط أولياء الأمور (QR)</button>' : ""}</div>
            ${studs.length ? `<div class="table-wrap"><table class="admin-table"><thead><tr><th>الاسم</th><th>اسم المستخدم</th><th></th></tr></thead><tbody>
            ${studs.map((x) => `<tr><td>${esc(x.full_name_ar)}</td><td dir="ltr" style="text-align:start">${esc(x.username)}</td>
              <td><button class="btn btn-ghost btn-small" data-reset="${x.id}" data-name="${esc(x.full_name_ar)}" data-user="${esc(x.username)}">كلمة مرور جديدة وبطاقة</button>
              <button class="btn btn-ghost btn-small" data-parent="${x.id}" data-name="${esc(x.full_name_ar)}">حساب ولي الأمر</button></td></tr>`).join("")}
            </tbody></table></div>` : '<p class="muted">لا يوجد طلاب في هذا الفصل بعد.</p>'}`;
        }
        body = (classes || []).length ? `
          <div class="field" style="max-width:420px"><label for="selClass">الفصل</label><select id="selClass">${classes.map((c) => `<option value="${c.id}" ${c.id === cid ? "selected" : ""}>${clsLabel(c)}</option>`).join("")}</select></div>
          <div class="form-card" style="max-width:none;margin:16px 0">
            <h3>إضافة طلاب</h3>
            <p class="muted">انسخ عمود الأسماء من Excel والصقه هنا، كل اسم في سطر. تُنشأ لكل طالب اسم مستخدم وكلمة مرور تلقائيًا، ثم تطبع بطاقات الدخول.</p>
            <div class="field"><textarea id="names" rows="8" placeholder="محمد أحمد&#10;فاطمة علي&#10;..."></textarea></div>
            <button class="btn btn-primary" id="addStudents">إنشاء الحسابات</button>
            <div id="created"></div>
          </div>${list}`
          : `<div class="empty"><strong>أنشئ فصلًا أولًا</strong><a href="#/teacher?setup=1">من «إضافة الفصول وتعديلها»</a></div>`;
      } else {
        const { data: ct } = await sb.from("class_teachers").select("class_id, teacher_id").in("class_id", (classes || []).map((c) => c.id).concat(["00000000-0000-0000-0000-000000000000"]));
        const clsOf = {}; (ct || []).forEach((r) => { (clsOf[r.teacher_id] = clsOf[r.teacher_id] || []).push(r.class_id); });
        state._mg = { classes: classes || [], clsOf, clsLabel };
        const inviteUrl = school.teacher_invite ? appUrl() + "#/join/" + school.teacher_invite : "";
        body = `<div class="staff-cards">
          <div class="form-card staff-card">
            <h3>الطريقة الأسهل: رابط دعوة</h3>
            <p class="muted">أرسل الرابط لمعلمي مدرستك عبر واتساب أو البريد. يفتحه المعلم، ويكتب اسمه وبريده وكلمة مروره، فيُنشأ حسابه في مدرستك مباشرة.</p>
            ${inviteUrl ? `<div class="invite-box"><input id="invUrl" readonly dir="ltr" value="${esc(inviteUrl)}"></div>
              <div class="invite-actions"><button class="btn btn-primary btn-small" id="invCopy">نسخ الرابط</button>
                <a class="btn btn-ghost btn-small wa-share" target="_blank" rel="noopener" href="https://wa.me/?text=${encodeURIComponent("السلام عليكم، هذا رابط الانضمام إلى منصة حراء في " + school.name_ar + ":\n" + inviteUrl)}">مشاركة بالواتساب</a>
                <button class="btn btn-ghost btn-small" id="invNew">رابط جديد</button>
                <button class="btn btn-ghost btn-small" id="invOff">إيقاف الرابط</button></div>
              <p class="muted" style="font-size:.85rem;margin-top:8px">أوقف الرابط بعد انضمام المعلمين، أو أنشئ رابطًا جديدًا فيتوقف القديم.</p>`
              : `<button class="btn btn-primary" id="invMake">إنشاء رابط دعوة</button>`}
          </div>
          <div class="form-card staff-card">
            <h3>أو أضفهم دفعة واحدة</h3>
            <p class="muted">كل معلم في سطر: الاسم ثم البريد. يمكنك نسخ العمودين من Excel ولصقهما هنا.</p>
            <div class="field"><textarea id="tbulk" rows="5" placeholder="أحمد علي، ahmed@school.ae&#10;مريم سالم، mariam@school.ae"></textarea></div>
            ${isSuper() ? '<label class="check"><input type="checkbox" id="tbAdmin"> إنشاؤهم بصلاحية «مدير مدرسة»</label>' : ""}
            <button class="btn btn-primary" id="tbGo" style="margin-top:10px">إنشاء الحسابات</button>
            <div id="tbOut"></div>
          </div>
        </div>
        <h3 style="margin:28px 0 10px">المعلمون (${(staff || []).length})</h3>
        <div class="table-wrap"><table class="admin-table"><thead><tr><th>الاسم</th><th>الدور</th><th>الفصول</th><th></th></tr></thead><tbody>
        ${(staff || []).map((x) => { const my = (clsOf[x.id] || []).map((cid) => (classes || []).find((c) => c.id === cid)).filter(Boolean);
          return `<tr><td>${esc(x.full_name_ar)}</td><td>${x.role === "teacher" ? ((x.hod_subjects || []).length ? `<b>رئيس قسم:</b> ${deptNames(x.hod_subjects)}` : "معلم") : "مدير مدرسة"}
            ${x.role === "teacher" && !hod ? `<div class="hod-pick" data-hodu="${x.id}">${DEPTS.map((d) => `<label><input type="checkbox" value="${d[0]}" ${(x.hod_subjects || []).includes(d[0]) ? "checked" : ""}> ${d[1].replace("التربية ", "").replace("الدراسات ", "")}</label>`).join("")}</div>` : ""}</td>
          <td>${my.length ? my.map((c) => `<span class="pill">${esc(c.name)} · ${SUBJECTS[SUBJECT_BY_ID[c.subject_id]].name.replace("التربية ", "")}</span>`).join(" ") : '<span class="muted">لم يُسند بعد</span>'}</td>
          <td><button class="btn ${my.length ? "btn-ghost" : "btn-dawn"} btn-small" data-tcls="${x.id}" data-name="${esc(x.full_name_ar)}">${my.length ? "تعديل الفصول" : "إسناد فصول"}</button>
            <button class="btn btn-ghost btn-small" data-sreset="${x.id}">كلمة مرور جديدة</button>
</td></tr>`; }).join("") || '<tr><td colspan="4" class="muted">لا يوجد معلمون بعد.</td></tr>'}
        </tbody></table></div>`;
      }
    }
    const link = school ? appUrl() + "#/school/" + school.code : "";
    h(`<section class="page-head"><div class="wrap">
        <div class="crumbs">إدارة المدرسة</div><h1>${school ? esc(school.name_ar) : "إدارة المدرسة"}</h1>
        ${school ? `<p class="muted">رابط دخول طلاب المدرسة: <a href="${link}" dir="ltr">${esc(link)}</a> <button class="btn btn-ghost btn-small" id="copyLink">نسخ</button> <button class="btn btn-ghost btn-small" id="editCode">تغيير الرمز</button></p>` : ""}
        <div class="controls">
          ${isSuper() ? `<div class="field" style="margin:0"><select id="selSchool">${(schools || []).map((x) => `<option value="${x.id}" ${x.id === sid ? "selected" : ""}>${esc(x.name_ar)}</option>`).join("")}<option value="__new">+ مدرسة جديدة</option></select></div>` : "<span></span>"}
          <div class="term-tabs"><a class="term-tab" style="text-decoration:none" href="${base("students")}" aria-selected="${tab === "students"}">الطلاب</a>
            <a class="term-tab" style="text-decoration:none" href="${base("staff")}" aria-selected="${tab === "staff"}">المعلمون</a>
            <a class="term-tab" style="text-decoration:none" href="#/teacher?setup=1">إضافة الفصول وتعديلها</a>
            <a class="term-tab" style="text-decoration:none" href="#/access">أذونات المحتوى</a>
            <a class="term-tab" style="text-decoration:none" href="#/overview">نظرة على المدرسة</a>
            <a class="term-tab" style="text-decoration:none" href="#/import">استيراد من Excel</a></div>
        </div></div></section>
      <section class="section" style="padding-top:34px"><div class="wrap">${body}</div></section>`);

    const ss = document.getElementById("selSchool");
    if (ss) ss.onchange = async () => {
      if (ss.value !== "__new") { location.hash = `#/manage?school=${ss.value}&tab=${tab}`; return; }
      const name = prompt("اسم المدرسة:"); if (!name) { ss.value = sid || ""; return; }
      const code = (prompt("رمز المدرسة بالإنجليزية (يظهر في رابط الدخول):", "") || "").trim().toLowerCase();
      if (!/^[a-z0-9-]{3,40}$/.test(code)) { toast("الرمز: حروف إنجليزية صغيرة وأرقام فقط، 3 أحرف على الأقل"); ss.value = sid || ""; return; }
      const r = await sb.from("schools").insert({ name_ar: name.trim(), code }).select("id").single();
      if (r.error) { toast("تعذّر الإنشاء: " + r.error.message); return; }
      location.hash = `#/manage?school=${r.data.id}&tab=${tab}`;
    };
    const ec = document.getElementById("editCode");
    if (ec) ec.onclick = async () => {
      const code = (prompt("رمز المدرسة الجديد بالإنجليزية (يظهر في رابط الدخول وبطاقات الطلاب):", school.code) || "").trim().toLowerCase();
      if (!code || code === school.code) return;
      if (!/^[a-z0-9-]{3,40}$/.test(code)) { toast("الرمز: حروف إنجليزية صغيرة وأرقام وشرطة فقط، 3 أحرف على الأقل"); return; }
      if (!confirm("تنبيه: بطاقات الدخول المطبوعة سابقًا تحمل الرمز القديم وستتوقف عن العمل، ويحتاج الطلاب بطاقات جديدة. هل تريد المتابعة؟")) return;
      const r = await sb.from("schools").update({ code }).eq("id", school.id);
      if (r.error) { toast(/duplicate|unique/i.test(r.error.message) ? "هذا الرمز مستخدم لمدرسة أخرى" : "تعذّر الحفظ: " + r.error.message); return; }
      toast("تغيّر الرمز"); pageManage(params);
    };
    document.querySelectorAll("[data-hodu]").forEach((box) => box.querySelectorAll("input").forEach((x) => x.onchange = async () => {
      const subs = [...box.querySelectorAll("input:checked")].map((y) => Number(y.value));
      const { error } = await sb.rpc("set_hod", { p_user: box.dataset.hodu, p_subjects: subs });
      if (error) { toast(error.message); x.checked = !x.checked; return; }
      toast(subs.length ? CT("عُيّن رئيسًا لقسم: ", "Head of: ") + deptNames(subs) : CT("أُلغيت رئاسة القسم", "Head-of-department role removed"));
    }));
    document.getElementById("main").classList.toggle("hod-view", hod);
    const fcb = document.getElementById("famCards"); if (fcb) fcb.onclick = () => printFamilyCards(state._famStuds || [], (classes || []).find((c) => c.id === (params.get("class") || (classes[0] && classes[0].id))));
    const cl = document.getElementById("copyLink");
    if (cl) cl.onclick = () => navigator.clipboard.writeText(link).then(() => toast("نُسخ الرابط"));
    const sc = document.getElementById("selClass");
    if (sc) sc.onchange = () => { location.hash = base("students", "&class=" + sc.value); };
    const add = document.getElementById("addStudents");
    if (add) add.onclick = async () => {
      const names = document.getElementById("names").value.split(/\r?\n/).map((x) => x.split("\t")[0].trim()).filter((x) => x.length >= 2);
      if (!names.length) { toast("الصق أسماء الطلاب أولًا"); return; }
      if (names.length > 60) { toast("60 طالبًا كحد أقصى في المرة الواحدة"); return; }
      add.disabled = true; add.textContent = "جارٍ الإنشاء…";
      try {
        const r = await callManage({ action: "create_students", class_id: sc.value, students: names.map((n) => ({ name: n })) });
        const ok = r.results.filter((x) => !x.error), bad = r.results.filter((x) => x.error);
        state._lastCreated = ok;
        document.getElementById("created").innerHTML = `<div class="notice"><strong>أُنشئ ${ok.length} حسابًا</strong>${bad.length ? ` · تعذّر ${bad.length}: ${bad.map((b) => esc(b.name)).join("، ")}` : ""}
          <p class="muted">احفظ هذه البيانات أو اطبع البطاقات الآن، فكلمات المرور لا تظهر مرة أخرى.</p>
          <button class="btn btn-dawn btn-small" id="printNew">طباعة بطاقات الدخول</button></div>
          <div class="table-wrap"><table class="admin-table"><thead><tr><th>الاسم</th><th>اسم المستخدم</th><th>كلمة المرور</th></tr></thead><tbody>
          ${ok.map((x) => `<tr><td>${esc(x.name)}</td><td dir="ltr" style="text-align:start">${esc(x.username)}</td><td dir="ltr" style="text-align:start">${esc(x.password)}</td></tr>`).join("")}</tbody></table></div>`;
        document.getElementById("printNew").onclick = () => printCards(school.name_ar, school.code, ok);
      } catch (e) { toast("تعذّر الإنشاء: " + e.message); }
      add.disabled = false; add.textContent = "إنشاء الحسابات";
    };
    main.querySelectorAll("[data-parent]").forEach((b) => b.addEventListener("click", async () => {
      const existing = prompt("لإنشاء حساب جديد لولي أمر " + b.dataset.name + " اترك الخانة فارغة واضغط موافق.\nولربطه بحساب ولي أمر موجود (لأخ أو أخت في المدرسة) اكتب اسم مستخدم ولي الأمر:", "");
      if (existing === null) return;
      try {
        const r = await callManage({ action: "create_parent", student_id: b.dataset.parent, existing_username: existing.trim() || undefined });
        if (r.linked) { toast("رُبط ولي الأمر بالطالب"); return; }
        printCards(school.name_ar, school.code, [{ name: r.name, username: r.username, password: r.password, child: b.dataset.name }], "ولي أمر الطالب");
      } catch (e) { toast("تعذّر: " + e.message); }
    }));
    main.querySelectorAll("[data-reset]").forEach((b) => b.addEventListener("click", async () => {
      if (!confirm("إنشاء كلمة مرور جديدة لـ " + b.dataset.name + "؟ ستتوقف كلمة المرور القديمة.")) return;
      try {
        const r = await callManage({ action: "reset_password", user_id: b.dataset.reset });
        printCards(school.name_ar, school.code, [{ name: b.dataset.name, username: b.dataset.user, password: r.password }]);
      } catch (e) { toast("تعذّر: " + e.message); }
    }));
    // invite link
    const invAct = async (off) => { try { await callManage({ action: "make_invite", school_id: sid, off }); toast(off ? "أُوقف الرابط" : "جاهز"); pageManage(params); } catch (e) { toast("تعذّر: " + e.message); } };
    const im = document.getElementById("invMake"); if (im) im.onclick = () => invAct(false);
    const inew = document.getElementById("invNew"); if (inew) inew.onclick = () => { if (confirm("سيتوقف الرابط القديم. هل تريد إنشاء رابط جديد؟")) invAct(false); };
    const ioff = document.getElementById("invOff"); if (ioff) ioff.onclick = () => { if (confirm("إيقاف رابط الدعوة؟")) invAct(true); };
    const ic = document.getElementById("invCopy"); if (ic) ic.onclick = () => navigator.clipboard.writeText(document.getElementById("invUrl").value).then(() => toast("نُسخ الرابط"));
    // bulk add
    const tb = document.getElementById("tbGo");
    if (tb) tb.onclick = async () => {
      const rows = document.getElementById("tbulk").value.split(/\r?\n/).map((l) => l.trim()).filter(Boolean).map((l) => {
        const em = (l.match(/[^\s,،\t;]+@[^\s,،\t;]+\.[^\s,،\t;]+/) || [])[0] || "";
        const name = l.replace(em, "").replace(/[,،\t;]+/g, " ").trim();
        return { name, email: em };
      });
      const bad = rows.filter((r) => !r.email || r.name.length < 2);
      if (!rows.length) { toast("الصق أسماء المعلمين وبريدهم أولًا"); return; }
      if (bad.length) { toast("كل سطر يحتاج اسمًا وبريدًا صحيحًا: " + bad.map((b) => b.name || b.email || "سطر فارغ").join("، ")); return; }
      tb.disabled = true; const out = [];
      for (const [k, r] of rows.entries()) {
        tb.textContent = `جارٍ الإنشاء ${k + 1} من ${rows.length}…`;
        try { const x = await callManage({ action: "create_staff", school_id: sid, role: (document.getElementById("tbAdmin") || {}).checked ? "school_admin" : "teacher", name: r.name, email: r.email }); out.push({ ...r, password: x.password }); }
        catch (e) { out.push({ ...r, error: e.message }); }
      }
      tb.disabled = false; tb.textContent = "إنشاء الحسابات";
      const ok = out.filter((x) => !x.error);
      const loginUrl = appUrl() + "#/login";
      const msg = (x) => `السلام عليكم ${x.name}،\nحسابك على منصة حراء (${school.name_ar}):\nالرابط: ${loginUrl}\nاختر «معلم أو إدارة»\nالبريد: ${x.email}\nكلمة المرور: ${x.password}`;
      document.getElementById("tbOut").innerHTML = `<div class="notice"><strong>أُنشئ ${ok.length} حسابًا</strong>${out.length - ok.length ? ` · تعذّر ${out.length - ok.length}` : ""}
        <p class="muted">أرسل لكل معلم بياناته بزر الواتساب. كلمات المرور لا تظهر مرة أخرى.</p></div>
        <div class="table-wrap"><table class="admin-table"><tbody>${out.map((x) => `<tr><td>${esc(x.name)}</td><td dir="ltr" style="text-align:start">${esc(x.email)}</td>
          <td>${x.error ? `<span class="lv needs_support">${esc(x.error)}</span>` : `<b dir="ltr">${esc(x.password)}</b>`}</td>
          <td>${x.error ? "" : `<a class="btn btn-ghost btn-small" target="_blank" rel="noopener" href="https://wa.me/?text=${encodeURIComponent(msg(x))}">واتساب</a>`}</td></tr>`).join("")}</tbody></table></div>
        <button class="btn btn-ghost btn-small" id="tbDone">تحديث القائمة وإسناد الفصول</button>`;
      document.getElementById("tbDone").onclick = () => pageManage(params);
    };
    // assign classes
    main.querySelectorAll("[data-tcls]").forEach((b) => b.addEventListener("click", () => {
      const tid = b.dataset.tcls, M = state._mg, mine = new Set(M.clsOf[tid] || []);
      let d = document.getElementById("tclsDlg");
      if (!d) { d = document.createElement("dialog"); d.id = "tclsDlg"; d.className = "wide-dlg"; document.body.appendChild(d); }
      const byGrade = {}; M.classes.forEach((c) => { (byGrade[c.year_group] = byGrade[c.year_group] || []).push(c); });
      d.innerHTML = `<h2 style="font-size:1.2rem">فصول ${esc(b.dataset.name)}</h2>
        ${M.classes.length ? `<p class="muted">اضغط على الفصول التي يدرّسها.</p>
        <div class="tcls-grid">${Object.keys(byGrade).sort((x, y) => x - y).map((g) => `<div class="tcls-row"><span class="tcls-g" dir="ltr">Grade ${g}</span>
          ${byGrade[g].map((c) => `<button type="button" class="chip tc" data-c="${c.id}" aria-pressed="${mine.has(c.id)}">${esc(c.name)} · ${SUBJECTS[SUBJECT_BY_ID[c.subject_id]].name.replace("التربية ", "")} · ${c.track === "native" ? "ناطقون" : "غير ناطقين"}</button>`).join("")}</div>`).join("")}</div>`
          : '<p class="muted">لا توجد فصول بعد. أنشئها أولًا من «فصولي» ← الإعداد السريع.</p>'}
        <div class="dialog-actions"><button class="btn btn-primary" id="tcSave">حفظ</button><button class="btn btn-ghost" id="tcX">إلغاء</button></div>`;
      d.querySelectorAll(".tc").forEach((x) => x.onclick = () => x.setAttribute("aria-pressed", String(x.getAttribute("aria-pressed") !== "true")));
      d.querySelector("#tcX").onclick = () => d.close();
      d.querySelector("#tcSave").onclick = async () => {
        const want = new Set([...d.querySelectorAll('.tc[aria-pressed="true"]')].map((x) => x.dataset.c));
        const add = [...want].filter((c) => !mine.has(c)), del = [...mine].filter((c) => !want.has(c));
        if (add.length) { const r = await sb.from("class_teachers").insert(add.map((c) => ({ class_id: c, teacher_id: tid }))); if (r.error) { toast("تعذّر الحفظ: " + r.error.message); return; } }
        if (del.length) { const r = await sb.from("class_teachers").delete().eq("teacher_id", tid).in("class_id", del); if (r.error) { toast("تعذّر الحفظ: " + r.error.message); return; } }
        d.close(); toast("حُفظت الفصول"); pageManage(params);
      };
      d.showModal();
    }));
    main.querySelectorAll("[data-sreset]").forEach((b) => b.addEventListener("click", async () => {
      if (!confirm("إنشاء كلمة مرور جديدة لهذا الحساب؟")) return;
      try { const r = await callManage({ action: "reset_password", user_id: b.dataset.sreset }); prompt("كلمة المرور الجديدة (انسخها وأرسلها للمعلم):", r.password); }
      catch (e) { toast("تعذّر: " + e.message); }
    }));
  }

  let ttsWarned = false;
  function speak(text, lang, audioUrl) { return; /* read-aloud of questions disabled: sound is only for Qur'an recitation, recordings and video */
    try { speechSynthesis.cancel(); } catch (e) {}
    if (audioUrl) { new Audio(audioUrl).play().catch(() => {}); return; }
    if (!("speechSynthesis" in window)) { toast("جهازك لا يدعم القراءة الصوتية"); return; }
    const voices = speechSynthesis.getVoices();
    const want = lang === "en" ? "en" : "ar";
    const v = voices.find((x) => x.lang && x.lang.toLowerCase().startsWith(want));
    if (!v && voices.length && !ttsWarned) { ttsWarned = true; toast(want === "ar" ? "لا يوجد صوت عربي مثبّت على هذا الجهاز" : "No English voice installed on this device"); }
    const u = new SpeechSynthesisUtterance(String(text).replace(/[﴿﴾«»]/g, ""));
    u.lang = want === "ar" ? "ar-SA" : "en-GB"; if (v) u.voice = v; u.rate = 0.85;
    speechSynthesis.speak(u);
  }
  try { speechSynthesis.getVoices(); speechSynthesis.onvoiceschanged = () => {}; } catch (e) {}
  const spk = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M4 9v6h4l5 4V5L8 9H4z"/><path d="M16 9a4 4 0 0 1 0 6M18.5 6.5a8 8 0 0 1 0 11"/></svg>';

  async function pageParent() {
    setTimeout(maybeTour, 900);
    loading();
    const en = LANG === "en";
    const { data: links } = await sb.from("parent_links").select("student_id").eq("parent_id", state.session.user.id);
    const ids = (links || []).map((x) => x.student_id);
    if (!ids.length && !state.independent) { h(`<section class="section"><div class="wrap" style="max-width:560px">${famLinkBox(en, true)}</div></section>`); famLinkWire(en); return; }
    const weekAgo = new Date(Date.now() - 7 * 86400000).toISOString();
    const [{ data: kids }, { data: atts }, { data: views }] = await Promise.all([
      sb.from("profiles").select("id, full_name_ar, year_group, track, username").in("id", ids.length ? ids : ["00000000-0000-0000-0000-000000000000"]),
      sb.from("attempts").select("id, student_id, score, max_score, submitted_at, assessment_id, assessments(id, kind, term, title_ar, title_en, track)").in("student_id", ids).not("submitted_at", "is", null).order("submitted_at", { ascending: false }),
      sb.from("lesson_views").select("student_id, last_seen, lessons(code, title_ar, title_en)").in("student_id", ids).gte("last_seen", weekAgo).order("last_seen", { ascending: false })
    ]);
    h(`<section class="page-head"><div class="wrap" style="padding-bottom:30px">
        <h1>${en ? "Welcome" : "أهلًا"} ${esc(state.profile.full_name_ar || "")}</h1>
        <p class="muted">${en ? "Follow your children's learning: lessons this week, test results, and what to review together." : "تابع تعلّم أبنائك: دروس هذا الأسبوع، ونتائج الاختبارات، وما يحتاجون مراجعته معك."}</p></div></section>
      ${state.independent ? `<section class="section" style="padding:24px 0 0"><div class="wrap"><details class="msgs add-child" ${ids.length ? "" : "open"}><summary><strong>+ ${en ? "Add a child" : "إضافة ابن أو ابنة"}</strong></summary>
        <div class="qs-body">
          <div class="field"><label for="kN">${en ? "Child's name" : "اسم الابن"}</label><input id="kN"></div>
          <p class="pref-label">${en ? "Grade" : "الصف"}</p><div class="qs-grades">${Array.from({ length: 12 }, (_, i) => `<button type="button" class="qs-g" data-kg="${i + 1}" aria-pressed="false">${i + 1}</button>`).join("")}</div>
          <div class="qs-row"><div><p class="pref-label">${en ? "Track" : "المسار"}</p><div class="seg"><button type="button" data-ktr="native" aria-pressed="${!en}">${en ? "Arabic speakers" : "الناطقون بالعربية"}</button><button type="button" data-ktr="non_native" aria-pressed="${en}">${en ? "Non-Arabic speakers" : "غير الناطقين"}</button></div></div>
            </div>
          <button class="btn btn-primary" id="kGo">${en ? "Create the account" : "إنشاء حساب الطفل"}</button>
          <p class="muted" style="font-size:.85rem">${en ? "No password to remember: on this device your child opens Hiraa from your account with one tap. On another device they can use the printed card." : "لا كلمة مرور يتذكّرها الطفل: على هذا الجهاز يدخل ابنك من حسابك بضغطة واحدة، وعلى جهاز آخر يستخدم البطاقة المطبوعة."}</p>
        </div></details></div></section>` : ""}
      <section class="section" style="padding-top:30px"><div class="wrap kids">
      ${(kids || []).map((k) => {
        const kAtts = (atts || []).filter((a) => a.student_id === k.id);
        const kViews = (views || []).filter((v) => v.student_id === k.id && v.lessons);
        return `<div class="kid-card"><div class="kid-top"><h2>${esc(k.full_name_ar)}</h2><button class="btn btn-dawn kid-go" data-famgo="${k.id}" data-kname="${esc(k.full_name_ar)}">▶ ${en ? "Start learning as " : "ادخل كـ"}${esc(String(k.full_name_ar || "").split(" ")[0])}</button></div><p class="muted">Grade ${k.year_group}${state.independent ? ` · <a href="#/year/${k.year_group}?track=${k.track}">${en ? "Lessons" : "الدروس"}</a> · <button class="linklike" data-kreset="${k.id}" data-kname="${esc(k.full_name_ar)}">${en ? "New login card" : "بطاقة دخول جديدة"}</button>` : ""}</p>
          ${state.independent ? `<div class="kid-acc" data-kid-acc="${k.id}" data-kg="${k.year_group}"></div>` : ""}
          <div class="kid-week" data-kid-week="${k.id}" data-kname="${esc(k.full_name_ar)}"></div>
          <div class="kid-hw" data-kid-hw="${k.id}"></div>
          <h3>${en ? "Lessons opened this week" : "دروس فتحها هذا الأسبوع"} (${kViews.length})</h3>
          ${kViews.length ? `<ul class="kid-list">${kViews.slice(0, 8).map((v) => `<li><a href="#/lesson/${esc(v.lessons.code)}">${esc(en && v.lessons.title_en ? v.lessons.title_en : v.lessons.title_ar)}</a></li>`).join("")}</ul>` : `<p class="muted">${en ? "No lessons opened this week." : "لم يفتح دروسًا هذا الأسبوع."}</p>`}
          <h3>${en ? "Test results" : "نتائج الاختبارات"}</h3>
          ${kAtts.length ? kAtts.map((a) => `<a class="test-card done" href="#/result/${a.assessment_id}?s=${k.id}"><strong>${esc(tTitle(a.assessments))}</strong>
            <span>${a.score}/${a.max_score} · ${new Date(a.submitted_at).toLocaleDateString(LANG === "en" ? "en-GB" : "ar-AE")} · ${en ? "View mastery map" : "اعرض خريطة الإتقان"}</span></a>`).join("") : `<p class="muted">${en ? "No tests taken yet." : "لم يؤدِّ اختبارات بعد."}</p>`}
        </div>`; }).join("")}
      </div></section>`);
    // weekly summary: four numbers, one thing to help with, and a WhatsApp share
    for (const box of [...main.querySelectorAll("[data-kid-week]")]) {
      const kid = box.dataset.kidWeek, name = box.dataset.kname;
      const { data: w } = await sb.rpc("child_week", { p_student: kid });
      if (!w) continue;
      const weak = w.weak;
      const lines = en ? [`${name}'s week on Hira:`, `📖 ${w.lessons} lessons opened`, `🎮 ${w.games} games · ${w.points} points`, `🧠 ${w.memo} hadiths reviewed · ${w.memo_known}/42 memorised`, ...(w.tests || []).map((t) => `✅ ${t.title_en || t.title}: ${t.score}/${t.max}`), weak ? `To review together: ${weak.outcome_en || weak.outcome}` : ""]
        : [`أسبوع ${name} على حراء:`, `📖 ${w.lessons} دروس فتحها`, `🎮 ${w.games} ألعاب · ${w.points} نقطة`, `🧠 راجع ${w.memo} أحاديث · حفظ ${w.memo_known} من 42`, ...(w.tests || []).map((t) => `✅ ${t.title}: ${t.score}/${t.max}`), weak ? `للمراجعة معه: ${weak.outcome}` : ""];
      const msg = lines.filter(Boolean).join("\n");
      box.innerHTML = `<div class="week-card"><h3>${en ? "This week" : "ملخص الأسبوع"}</h3>
        <div class="week-nums"><div><b>${w.lessons}</b><span>${en ? "lessons" : "دروس"}</span></div><div><b>${w.games}</b><span>${en ? "games" : "ألعاب"}</span></div><div><b>${w.points}</b><span>${en ? "points" : "نقطة"}</span></div><div><b>${w.memo_known}/42</b><span>${en ? "hadiths memorised" : "حديثًا حفظه"}</span></div></div>
        ${weak ? `<p class="week-help">💡 <b>${en ? "Help with:" : "ساعده في:"}</b> ${esc(en && weak.outcome_en ? weak.outcome_en : weak.outcome)}${weak.lesson ? ` · <a href="#/lesson/${esc(weak.lesson)}">${en ? "open the lesson" : "افتح الدرس"}</a>` : ""}</p>`
          : `<p class="muted">${en ? "No outcome needs extra help right now." : "لا يوجد ناتج يحتاج دعمًا الآن."}</p>`}
        <div class="week-acts"><a class="btn btn-ghost btn-small" target="_blank" rel="noopener" href="https://wa.me/?text=${encodeURIComponent(msg)}">${en ? "Share on WhatsApp" : "شاركه على واتساب"}</a>
          <button class="btn btn-ghost btn-small" data-wcopy>${en ? "Copy" : "نسخ"}</button></div></div>`;
      box.querySelector("[data-wcopy]").onclick = () => { navigator.clipboard && navigator.clipboard.writeText(msg); toast(en ? "Copied" : "نُسخ الملخص"); };
    }
    for (const box of [...main.querySelectorAll("[data-kid-hw]")]) {
      const kid = box.dataset.kidHw;
      const { data: kc } = await sb.from("class_students").select("class_id").eq("student_id", kid);
      if (!(kc || []).length) continue;
      const { data: A } = await sb.from("assignments").select("id, title_ar, lesson_id, tasks, due_at, created_at").in("class_id", kc.map((x) => x.class_id)).order("created_at", { ascending: false }).limit(5);
      if (!(A || []).length) continue;
      const pr = await hwProgress(A, [kid]);
      box.innerHTML = `<h3>${en ? "Homework" : "الواجبات"}</h3><ul class="kid-hw-list">${A.map((a) => { const p = pr[a.id + "|" + kid] || {}; const late = a.due_at && new Date(a.due_at) < new Date() && !p.done;
        return `<li class="${p.done ? "ok" : late ? "late" : ""}">${p.done ? "✓" : late ? "!" : "○"} ${esc(a.title_ar)} <small class="muted">${p.done ? (en ? "done" : "أنجزه") : esc(dueTxt(a.due_at))} · ${p.n || 0}/${p.tot || 0}</small>${p.sub && p.sub.grade != null ? ` <span class="hw-fb">${"★".repeat(Number(p.sub.grade))}</span>` : ""}${p.sub && p.sub.feedback_ar ? ` <small>«${esc(p.sub.feedback_ar)}»</small>` : ""}</li>`; }).join("")}</ul>`;
    }
    for (const box of [...main.querySelectorAll("[data-kid-acc]")]) {
      const kid = box.dataset.kidAcc, g = Number(box.dataset.kg);
      const [{ data: gr }, { data: rq }] = await Promise.all([sb.from("access_grants").select("year_group").eq("user_id", kid), sb.from("access_requests").select("id").eq("user_id", kid).eq("status", "pending")]);
      const has = (gr || []).some((x) => x.year_group == null || x.year_group === g);
      box.innerHTML = has ? `<span class="lv mastered">✓ ${en ? "Grade content open" : "محتوى الصف مفتوح"}</span>` : (rq || []).length ? `<span class="lv developing">⏳ ${en ? "Awaiting approval" : "بانتظار موافقة الإدارة"}</span>`
        : `<button class="btn btn-dawn btn-small" data-req-access="${g}" data-for="${kid}">${en ? "Request access" : "طلب فتح محتوى الصف"}</button>`;
    }
    let kg = null, ktr = en ? "non_native" : "native";
    main.querySelectorAll("[data-kg]").forEach((b) => b.onclick = () => { kg = Number(b.dataset.kg); main.querySelectorAll("[data-kg]").forEach((x) => x.setAttribute("aria-pressed", String(x === b))); });
    main.querySelectorAll("[data-ktr]").forEach((b) => b.onclick = () => { ktr = b.dataset.ktr; main.querySelectorAll("[data-ktr]").forEach((x) => x.setAttribute("aria-pressed", String(x === b))); });
    main.querySelectorAll("[data-famgo]").forEach((b) => b.onclick = () => famSwitch(b.dataset.famgo, b.dataset.kname, en));
    { const ex = document.createElement("section"); ex.className = "section"; ex.style.paddingTop = "0"; ex.innerHTML = `<div class="wrap" style="max-width:720px">${famLinkBox(en, false)}</div>`; main.appendChild(ex); famLinkWire(en); }
    const kgo = document.getElementById("kGo");
    if (kgo) kgo.onclick = async () => {
      const name = document.getElementById("kN").value.trim(), password = "";
      if (name.length < 2 || !kg) { toast(en ? "Enter the name and choose the grade" : "اكتب الاسم واختر الصف"); return; }
      kgo.disabled = true;
      try {
        const r = await callManage({ action: "add_child", name, grade: kg, track: ktr, password });
        await sb.rpc("request_access", { p_year: kg, p_note: "طلب ولي الأمر عند إضافة الابن", p_for: r.id });
        toast(en ? "Account created" : "أُنشئ حساب الطفل 🎉");
        if (confirm(en ? "Print a login card for using Hiraa on another device (e.g. a tablet)?" : "هل تريد طباعة بطاقة دخول لاستخدام حراء على جهاز آخر (مثل الآيباد)؟")) printCards("حراء للتعلّم الذاتي", r.school_code, [{ name: r.name, username: r.username, password: r.password }]);
        setTimeout(() => pageParent(), 800);
      } catch (e) { toast(e.message); kgo.disabled = false; }
    };
    main.querySelectorAll("[data-kreset]").forEach((b) => b.onclick = async () => {
      if (!confirm((en ? "Make a new login card for " : "إنشاء بطاقة دخول جديدة لـ ") + b.dataset.kname + "?")) return;
      try { const r = await callManage({ action: "reset_child", child_id: b.dataset.kreset }); const { data: kp } = await sb.from("profiles").select("username").eq("id", b.dataset.kreset).maybeSingle();
        printCards("حراء للتعلّم الذاتي", "hira", [{ name: b.dataset.kname, username: kp ? kp.username : "", password: r.password }]); } catch (e) { toast(e.message); }
    });
  }


  /* ===== rendering of all question types in tests ===== */
  const QT_AR = { mcq: "اختيار من متعدد", true_false: "صح أو خطأ", matching: "توصيل", ordering: "ترتيب", fill_blank: "أكمل الفراغ", short: "إجابة مكتوبة" };
  const qAnswered = (q, v) => (Array.isArray(v) ? v.some((x) => x) : !!(v && String(v).trim()));
  function qTypeBody(q, answers, nn, spk) {
    const t = q.qtype || "mcq", dir = nn ? 'dir="ltr"' : "", v = answers[q.id];
    const hint = (ar, en) => `<p class="q-hint">${nn ? en : ar}${q.pts && q.pts > 1 ? ` · ${q.pts} ${nn ? "marks" : "درجات"}` : ""}</p>`;
    if (t === "matching") { const L = q.options.left || [], R = q.rightSh || []; const cur = Array.isArray(v) ? v : [];
      return `${hint("صِل كل عنصر بما يناسبه", "Match each item")}<div class="q-match" ${dir}>${L.map((l, i) => `<div class="qm-row"><span>${esc(l)}</span><select data-mi="${i}"><option value="">${nn ? "Choose…" : "اختر…"}</option>${R.map((r) => `<option ${cur[i] === r ? "selected" : ""}>${esc(r)}</option>`).join("")}</select></div>`).join("")}</div>`; }
    if (t === "ordering") { const cur = Array.isArray(v) && v.length ? v : shuffle((q.options && q.options.items) || []); answers[q.id] = cur;
      return `${hint("رتّب العناصر بالأسهم", "Put the items in order using the arrows")}<ol class="q-order" ${dir}>${cur.map((x, i) => `<li><span>${esc(x)}</span><button type="button" data-up="${i}" ${i === 0 ? "disabled" : ""}>▲</button><button type="button" data-dn="${i}" ${i === cur.length - 1 ? "disabled" : ""}>▼</button></li>`).join("")}</ol>`; }
    if (t === "fill_blank") return `${hint("اكتب الكلمة المناسبة في الفراغ", "Type the missing word")}<input class="q-fill" id="qFill" ${dir} value="${esc(v || "")}" placeholder="${nn ? "Your answer" : "إجابتك"}">`;
    if (t === "short") return `${hint("اكتب إجابتك بأسلوبك، ويصحّحها معلمك", "Write your answer; your teacher will mark it")}<textarea class="q-short" id="qShort" rows="5" ${dir}>${esc(v || "")}</textarea>`;
    return `<div class="q-opts" ${dir}>${q.opts.map((o, k) => `<div class="q-opt-row"><button class="q-opt ${v === o.id ? "sel" : ""}" data-opt="${o.id}">${esc(o.text)}</button>
      <button class="speak-btn small" data-say="${k}" aria-label="${nn ? "Read this answer" : "استمع لهذه الإجابة"}">${spk}</button></div>`).join("")}</div>`;
  }
  function qTypeWire(q, answers, save, redraw) {
    const t = q.qtype || "mcq";
    if (t === "matching") main.querySelectorAll("[data-mi]").forEach((s) => s.onchange = () => { const cur = Array.isArray(answers[q.id]) ? answers[q.id].slice() : new Array(((q.options || {}).left || []).length).fill(""); cur[+s.dataset.mi] = s.value; answers[q.id] = cur; save(); });
    if (t === "ordering") { save(); const mv = (i, d) => { const c = answers[q.id].slice(); [c[i], c[i + d]] = [c[i + d], c[i]]; answers[q.id] = c; save(); redraw(); };
      main.querySelectorAll("[data-up]").forEach((b) => b.onclick = () => mv(+b.dataset.up, -1)); main.querySelectorAll("[data-dn]").forEach((b) => b.onclick = () => mv(+b.dataset.dn, 1)); }
    const f = document.getElementById("qFill"); if (f) f.oninput = () => { answers[q.id] = f.value; save(); };
    const s = document.getElementById("qShort"); if (s) s.oninput = () => { answers[q.id] = s.value; save(); };
  }

  async function pageTest(id) {
    setNav("");
    if (!state.session) { location.hash = "#/login"; return; }
    if (!isStudent()) { h('<div class="wrap loading">الاختبار للطلاب. يمكن للمعلم معاينة النتائج من صفحة «فصولي».</div>'); return; }
    loading();
    const { data: att, error } = await sb.rpc("start_attempt", { p_assessment: id });
    if (error) {
      if (/already taken/.test(error.message)) { location.hash = "#/result/" + id; return; }
      if (/unit_not_ready/.test(error.message)) { const { data: ua } = await sb.from("assessments").select("unit_id").eq("id", id).maybeSingle();
        h(`<div class="wrap"><div class="form-card empty"><strong>✋ ${CT("أكمل واجبات الوحدة أولًا", "Finish this unit's tasks first")}</strong>${CT("يُفتح تدريب الوحدة بعد أن تحلّ تذاكر الخروج لكل دروسها وتسلّم واجباتها.", "Unit practice opens after you complete every lesson's exit ticket and hand in the unit's homework.")}
          ${ua && ua.unit_id ? `<p><a class="btn btn-primary btn-small" href="#/unit/${ua.unit_id}">${CT("اعرض المهام الناقصة", "See what is missing")}</a></p>` : ""}</div></div>`); return; }
      if (/window closed/.test(error.message)) { h(`<div class="wrap loading">${LANG === "en" ? "This benchmark window is closed." : "نافذة هذا الاختبار المعياري مغلقة الآن."}</div>`); return; }
      h(`<div class="wrap loading">${state.viewAs ? CT("أنت في وضع المعاينة كطالب، ولا يمكن أداء الاختبارات في هذا الوضع. سجّل الدخول بحساب طالب لتجربته.", "You are previewing as a student; tests cannot be taken in preview. Sign in with a student account to try it.") : CT("لا يمكن بدء الاختبار الآن.", "The test cannot start now.")}</div>`); return;
    }
    const [{ data: a }, { data: aq }] = await Promise.all([
      sb.from("assessments").select("title_ar, title_en, year_group, track, kind").eq("id", id).single(),
      sb.from("assessment_questions").select("sort_order, points, questions(id, stem_ar, stem_en, options, audio_url, qtype)").eq("assessment_id", id).order("sort_order")
    ]);
    let qs = (aq || []).map((x) => x.questions ? { ...x.questions, pts: x.points } : null).filter(Boolean).map((q) => ({ ...q, opts: Array.isArray(q.options) ? shuffle(q.options) : [], rightSh: q.options && q.options.right ? shuffle(q.options.right) : null }));
    const practice = a && a.kind === "unit_practice", unitTest = a && a.kind === "unit_test";
    if (practice || unitTest) { const pk = "hira-set-" + att; let ids = null; try { ids = JSON.parse(localStorage.getItem(pk) || "null"); } catch (e) {}
      if (!ids) { ids = shuffle(qs.map((q) => q.id)).slice(0, practice ? ((a.year_group || 9) <= 3 ? 10 : 20) : qs.length); try { localStorage.setItem(pk, JSON.stringify(ids)); } catch (e) {} }
      const byId = {}; qs.forEach((q) => { byId[q.id] = q; }); qs = ids.map((x) => byId[x]).filter(Boolean); }
    const key = "hira-att-" + att;
    let answers = {}; try { answers = JSON.parse(localStorage.getItem(key) || "{}"); } catch (e) { answers = {}; }
    let i = 0;
    const nn = (a && a.track === "non_native") || LANG === "en";
    const draw = () => {
      const q = qs[i];
      const answered = Object.keys(answers).length;
      h(`<section class="test-wrap"><div class="wrap test-inner">
        <div class="test-top" ${nn ? 'dir="ltr"' : ""}><strong>${esc(tTitle(a))}</strong><span>${nn ? `${answered} of ${qs.length} answered` : `${answered} من ${qs.length} أُجيب`}</span></div>
        <div class="test-progress"><span style="width:${Math.round(((i + 1) / qs.length) * 100)}%"></span></div>
        <p class="q-num" ${nn ? 'dir="ltr"' : ""}>${nn ? `Question ${i + 1} of ${qs.length}` : `السؤال ${i + 1} من ${qs.length}`}</p>
        <div class="q-stem-row" ${nn ? 'dir="ltr"' : ""}><button class="speak-btn" data-say="stem" aria-label="${nn ? "Read aloud" : "استمع للسؤال"}">${spk}</button>
          <h1 class="q-stem">${esc(nn && q.stem_en ? q.stem_en : q.stem_ar)}</h1></div>
        ${qTypeBody(q, answers, nn, spk)}
        <div class="test-nav">
          <button class="btn btn-ghost" id="prevQ" ${i === 0 ? "disabled" : ""}>${nn ? "Previous" : "السابق"}</button>
          ${i < qs.length - 1 ? `<button class="btn btn-primary" id="nextQ">${nn ? "Next" : "التالي"}</button>` : `<button class="btn btn-dawn" id="finish">${nn ? "Finish the test" : "إنهاء الاختبار"}</button>`}
        </div>
        <div class="q-dots">${qs.map((x, k) => `<button class="q-dot ${qAnswered(x, answers[x.id]) ? "ok" : ""} ${k === i ? "cur" : ""}" data-go="${k}" aria-label="السؤال ${k + 1}">${k + 1}</button>`).join("")}</div>
      </div></section>`);
      const sayLang = nn ? "en" : "ar";
      main.querySelectorAll("[data-say]").forEach((b) => b.onclick = () => {
        const k = b.dataset.say;
        if (k === "stem") speak(nn && q.stem_en ? q.stem_en : q.stem_ar, sayLang, q.audio_url);
        else speak(q.opts[Number(k)].text, sayLang);
      });
      if (a && a.year_group <= 2 && draw._started) setTimeout(() => speak(nn && q.stem_en ? q.stem_en : q.stem_ar, sayLang, q.audio_url), 250);
      qTypeWire(q, answers, () => { try { localStorage.setItem(key, JSON.stringify(answers)); } catch (e) {} }, draw);
      main.querySelectorAll("[data-opt]").forEach((b) => b.onclick = () => {
        draw._started = true;
        answers[q.id] = b.dataset.opt; try { localStorage.setItem(key, JSON.stringify(answers)); } catch (e) {}
        if (i < qs.length - 1) { i++; } draw();
      });
      main.querySelectorAll("[data-go]").forEach((b) => b.onclick = () => { i = Number(b.dataset.go); draw(); });
      const pv = document.getElementById("prevQ"); if (pv) pv.onclick = () => { i--; draw(); };
      const nx = document.getElementById("nextQ"); if (nx) nx.onclick = () => { i++; draw(); };
      const fn = document.getElementById("finish");
      if (fn) fn.onclick = async () => {
        const missing = qs.filter((x) => !qAnswered(x, answers[x.id])).length;
        if (missing && !confirm(nn ? `You have not answered ${missing} question(s). Finish anyway?` : `لم تجب عن ${missing} من الأسئلة. هل تريد إنهاء الاختبار؟`)) return;
        fn.disabled = true;
        const payload = {}; qs.forEach((x) => { if (answers[x.id]) payload[x.id] = answers[x.id]; else if (practice) payload[x.id] = ""; });
        const { error: e2 } = await sb.rpc("submit_attempt", { p_attempt: att, p_answers: payload });
        if (e2) { toast("تعذّر الإرسال، حاول مرة أخرى"); fn.disabled = false; return; }
        try { localStorage.removeItem(key); } catch (e) {}
        try { localStorage.removeItem("hira-set-" + att); } catch (e) {}
        location.hash = (a && a.kind === "benchmark" ? "#/bench-report/" : "#/result/") + id;
      };
    };
    if (!qs.length) { h('<div class="wrap loading">لا توجد أسئلة في هذا الاختبار بعد.</div>'); return; }
    draw();
  }

  async function pageResult(id, params) {
    setNav("");
    if (!state.session) { location.hash = "#/login"; return; }
    loading();
    const viewing = params && params.get("s");
    const me = viewing || state.session.user.id;
    const [{ data: a }, { data: atts }, { data: aq }] = await Promise.all([
      sb.from("assessments").select("title_ar, title_en, kind, term, year_group, subject_id, track").eq("id", id).single(),
      sb.from("attempts").select("id, score, max_score, submitted_at").eq("assessment_id", id).eq("student_id", me).not("submitted_at", "is", null).order("submitted_at", { ascending: false }).limit(1),
      sb.from("assessment_questions").select("questions(id, outcome_id, learning_outcomes(id, code, statement_ar, statement_en, sort_order))").eq("assessment_id", id)
    ]);
    const att = (atts || [])[0];
    if (!att) { if (viewing) { h('<div class="wrap loading">لم يؤدِّ الطالب هذا الاختبار بعد.</div>'); return; } location.hash = "#/test/" + id; return; }
    const { data: ans } = await sb.from("attempt_answers").select("question_id, is_correct").eq("attempt_id", att.id);
    const correct = {}; (ans || []).forEach((x) => { correct[x.question_id] = !!x.is_correct; });
    const byOut = {};
    (aq || []).forEach((x) => { const q = x.questions; if (!q || !q.learning_outcomes) return;
      const o = q.learning_outcomes; (byOut[o.id] = byOut[o.id] || { o, n: 0, ok: 0 }); byOut[o.id].n++; if (correct[q.id]) byOut[o.id].ok++; });
    const outs = Object.values(byOut).sort((x, y) => x.o.sort_order - y.o.sort_order);
    const weakIds = outs.filter((x) => levelOf(x.ok / x.n) !== "mastered").map((x) => x.o.id);
    let lessonsFor = {};
    if (weakIds.length) {
      const { data: lo } = await sb.from("lesson_outcomes").select("outcome_id, lessons(code, title_ar, units(track, term))").in("outcome_id", weakIds);
      (lo || []).forEach((r) => { if (r.lessons && r.lessons.units && r.lessons.units.track === a.track) (lessonsFor[r.outcome_id] = lessonsFor[r.outcome_id] || []).push(r.lessons); });
    }
    // growth: compare with the diagnostic of the same term (same questions)
    let pre = null;
    if (a && a.kind === "post") {
      const { data: d } = await sb.from("assessments").select("id").eq("kind", "diagnostic").eq("year_group", a.year_group).eq("subject_id", a.subject_id).eq("track", a.track).eq("term", a.term).limit(1);
      if (d && d[0]) {
        const { data: pa } = await sb.from("attempts").select("id, score, max_score").eq("assessment_id", d[0].id).eq("student_id", me).not("submitted_at", "is", null).limit(1);
        if (pa && pa[0]) {
          const { data: pans } = await sb.from("attempt_answers").select("question_id, is_correct").eq("attempt_id", pa[0].id);
          const pc = {}; (pans || []).forEach((x) => { pc[x.question_id] = !!x.is_correct; });
          const pOut = {}; (aq || []).forEach((x) => { const q = x.questions; if (!q || !q.learning_outcomes) return; const oid = q.learning_outcomes.id; pOut[oid] = pOut[oid] || { n: 0, ok: 0 }; pOut[oid].n++; if (pc[q.id]) pOut[oid].ok++; });
          pre = { score: pa[0].score, max: pa[0].max_score, byOut: pOut };
        }
      }
    }
    const nnR = (a && a.track === "non_native") || LANG === "en";
    const pct = att.max_score ? Math.round((att.score / att.max_score) * 100) : 0;
    h(`<section class="page-head"><div class="wrap" style="padding-bottom:30px">
        <div class="crumbs"><a href="#/my">صفحتي</a></div>
        ${(() => { const stars = pct >= 80 ? 3 : pct >= 50 ? 2 : 1;
          const msg = nnR ? (pct >= 80 ? "Excellent work, keep it up!" : pct >= 50 ? "Good effort! A little review and you'll master it." : "Every expert was once a beginner. Let's review together!")
                          : (pct >= 80 ? "ممتاز، بارك الله فيك! واصل تميّزك." : pct >= 50 ? "أحسنت! قليل من المراجعة وتصل إلى الإتقان." : "كل متقن كان مبتدئًا يومًا، لنراجع معًا!");
          const grow = pre && att.score > pre.score ? (nnR ? ` You improved by ${att.score - pre.score}!` : ` تقدّمت ${att.score - pre.score} درجات عن التشخيصي!`) : "";
          return `<div class="cheer ${pct >= 80 ? "party" : ""}" ${nnR ? 'dir="ltr"' : ""}><span class="stars" aria-label="${stars}/3">${"★".repeat(stars)}<span class="off">${"★".repeat(3 - stars)}</span></span><strong>${msg}${grow}</strong>${pct >= 80 ? '<span class="confetti" aria-hidden="true">' + "<i></i>".repeat(14) + "</span>" : ""}</div>`; })()}
        <h1>${esc(tTitle(a) || "النتيجة")}</h1>
        <div class="score-line"><span class="score-big">${att.score}/${att.max_score}</span><span class="muted">${pct}% · ${new Date(att.submitted_at).toLocaleDateString(LANG === "en" ? "en-GB" : "ar-AE")}</span></div>
        ${!viewing ? `<div class="res-acts"><button class="btn btn-dawn" id="resCert">🏅 ${nnR ? "Certificate of appreciation" : "شهادة تقدير"}</button>${["diagnostic", "post", "benchmark", "unit_test", "teacher_test", "lesson_pre", "lesson_post"].includes(a.kind) ? "" : `<a class="btn btn-primary" href="#/test/${id}">🔁 ${nnR ? "Try again to improve" : "حاول مرة أخرى لتحسين درجتك"}</a>`}</div>` : ""}
        ${pre ? `<p class="growth-line">${nnR ? "Diagnostic" : "في التشخيصي"}: <b>${pre.score}/${pre.max}</b> ← ${nnR ? "Now" : "الآن"}: <b>${att.score}/${att.max_score}</b>
          ${att.score > pre.score ? `<span class="lv mastered">${nnR ? "Improved" : "تقدّم"} +${att.score - pre.score}</span>` : att.score < pre.score ? `<span class="lv needs_support">${att.score - pre.score}</span>` : `<span class="lv developing">${nnR ? "Same" : "ثابت"}</span>`}</p>` : ""}
      </div></section>
      <section class="section" style="padding-top:34px"><div class="wrap">
        <h2>خريطة إتقاني</h2>
        <div class="legend"><span class="lv mastered">أتقن</span><span class="lv developing">قريب من الإتقان</span><span class="lv needs_support">يحتاج دعمًا</span></div>
        <div class="mastery-list">${outs.map((x) => { const lv = levelOf(x.ok / x.n);
          const ls = (lessonsFor[x.o.id] || []).filter((v, k, arr) => arr.findIndex((y) => y.code === v.code) === k);
          const pb = pre && pre.byOut[x.o.id]; const plv = pb ? levelOf(pb.ok / pb.n) : null;
          return `<div class="m-item ${lv}"><div class="m-head"><span>${lv === "mastered" ? '<span class="badge-star" aria-hidden="true">⭐</span>' : ""}${plv && plv !== lv ? `<span class="lv ${plv}">${LEVEL_AR[plv]}</span> ← ` : ""}<span class="lv ${lv}">${LEVEL_AR[lv]}</span></span><code>${esc(x.o.code)}</code></div>
            <p>${esc(OT(x.o))}</p>
            ${lv !== "mastered" && ls.length ? `<div class="m-fix">راجع: ${ls.map((l) => `<a href="#/lesson/${esc(l.code)}">${esc(l.title_ar)}</a>`).join(" · ")}</div>` : ""}</div>`; }).join("")}</div>
      </div></section>`);
    const rc = document.getElementById("resCert"); if (rc) rc.onclick = () => printAppreciation({ title: tTitle(a), score: att.score, max: att.max_score, en: nnR, kind: "test" });
  }

  async function pageRecitations(params) {
    setNav("teacher");
    if (!state.session) { location.hash = "#/login"; return; }
    if (!isStaff()) { h('<div class="wrap loading">هذه الصفحة للمعلمين وإدارات المدارس.</div>'); return; }
    loading();
    const me = state.session.user.id;
    const { data: all } = await sb.from("classes").select("id, name, year_group, class_teachers(teacher_id)").order("year_group").order("name");
    const classes = state.profile.role === "teacher" ? (all || []).filter((c) => (c.class_teachers || []).some((t) => t.teacher_id === me)) : (all || []);
    const cls = classes.find((c) => c.id === params.get("class")) || classes[0];
    if (!cls) { h('<div class="wrap loading">لا توجد فصول بعد.</div>'); return; }
    const showAll = params.get("all") === "1";
    const { data: cs } = await sb.from("class_students").select("student_id, profiles(full_name_ar)").eq("class_id", cls.id);
    const names = {}; (cs || []).forEach((r) => { names[r.student_id] = r.profiles ? r.profiles.full_name_ar : ""; });
    let q = sb.from("recitations").select("id, student_id, title, audio_path, duration_sec, status, teacher_note, created_at").in("student_id", Object.keys(names).length ? Object.keys(names) : ["00000000-0000-0000-0000-000000000000"]).order("created_at", { ascending: false }).limit(100);
    if (!showAll) q = q.eq("status", "submitted");
    const { data: recs } = await q;
    const ST = { submitted: ["بانتظار التقييم", "developing"], mastered: ["أتقن", "mastered"], redo: ["يحتاج إعادة", "needs_support"] };
    h(`<section class="page-head"><div class="wrap">
        <div class="crumbs"><a href="#/teacher?class=${cls.id}">لوحة الفصل</a></div>
        <h1>التسميع</h1>
        <div class="controls"><div class="chips" style="margin:0">${classes.map((c) => `<a class="chip" href="#/recitations?class=${c.id}" aria-current="${c.id === cls.id}">${esc(c.name)} · Grade ${c.year_group}</a>`).join("")}</div>
          <div class="term-tabs"><a class="term-tab" style="text-decoration:none" href="#/recitations?class=${cls.id}" aria-selected="${!showAll}">بانتظار التقييم</a><a class="term-tab" style="text-decoration:none" href="#/recitations?class=${cls.id}&all=1" aria-selected="${showAll}">الكل</a></div></div>
      </div></section>
      <section class="section" style="padding-top:30px"><div class="wrap rec-review">
        ${(recs || []).length ? recs.map((r) => `<div class="m-item ${ST[r.status][1]}" data-rec="${r.id}">
          <div class="m-head"><strong>${esc(names[r.student_id] || "")}</strong><span><span class="lv ${ST[r.status][1]}">${ST[r.status][0]}</span> <span class="muted">${new Date(r.created_at).toLocaleString(LANG === "en" ? "en-GB" : "ar-AE")}</span></span></div>
          <p>${esc(r.title)}${r.duration_sec ? ` · ${Math.floor(r.duration_sec / 60)}:${String(r.duration_sec % 60).padStart(2, "0")}` : ""}</p>
          <button class="btn btn-ghost btn-small" data-listen="${esc(r.audio_path)}">استمع</button>
          <div class="rec-eval"><input class="rec-note" placeholder="ملاحظة للطالب (اختياري)" value="${esc(r.teacher_note || "")}">
            <button class="btn btn-primary btn-small" data-eval="mastered">أتقن</button><button class="btn btn-ghost btn-small" data-eval="redo">يحتاج إعادة</button></div></div>`).join("")
          : `<div class="empty"><strong>${showAll ? "لا توجد تسميعات بعد" : "لا توجد تسميعات بانتظار التقييم"}</strong>يسجّل الطلاب تسميعهم من تبويب «التسميع» في صفحة الدرس.</div>`}
      </div></section>`);
    main.querySelectorAll("[data-listen]").forEach((b) => b.addEventListener("click", async () => {
      const { data, error } = await sb.storage.from("recitations").createSignedUrl(b.dataset.listen, 3600);
      if (error) { toast("تعذّر تشغيل التسجيل"); return; }
      const au = document.createElement("audio"); au.controls = true; au.src = data.signedUrl; au.className = "rec-audio"; b.replaceWith(au); au.play().catch(() => {});
    }));
    main.querySelectorAll("[data-eval]").forEach((b) => b.addEventListener("click", async () => {
      const box = b.closest("[data-rec]");
      const { error } = await sb.from("recitations").update({ status: b.dataset.eval, teacher_note: box.querySelector(".rec-note").value.trim() || null, reviewed_by: me, reviewed_at: new Date().toISOString() }).eq("id", box.dataset.rec);
      if (error) { toast("تعذّر الحفظ: " + error.message); return; }
      toast(b.dataset.eval === "mastered" ? "قُيّم: أتقن" : "قُيّم: يحتاج إعادة");
      if (!showAll) box.remove(); else pageRecitations(params);
    }));
  }

  /* =================== COMPETITIONS =================== */
