  const rng = (a, b) => Array.from({ length: b - a + 1 }, (_, i) => a + i);
  const bandName = (g) => (!g || !g.length ? CT("كل الصفوف", "All grades") : Math.min(...g) === Math.max(...g) ? `Grade ${g[0]}` : `Grades ${Math.min(...g)}–${Math.max(...g)}`);
