      criteria: [], mode: "test", bank: [["الهمزة في كلمة «أحمد» همزة:", ["قطع", "وصل", "متوسطة", "متطرفة"], 0, ["L1", "L2"]], ["الهمزة في كلمة «استمع» همزة:", ["وصل", "قطع", "متوسطة", "متطرفة"], 0, ["L1", "L2"]], ["الكلمة المكتوبة بتاء مربوطة:", ["مدرسة", "بيت", "كتبت", "بنات"], 0, ["L1"]], ["الكلمة الصحيحة إملائيًّا:", ["مسؤول", "مسئول بالواو", "مسؤل", "مسوءول"], 0, ["L1", "L2"]], ["الألف اللينة في «مشى» تُكتب ياءً لأن أصلها:", ["ياء", "واو", "همزة", "ألف"], 0, ["L2", "L3"]], ["علامة الترقيم التي تأتي قبل القول:", ["النقطتان", "الفاصلة", "النقطة", "علامة التعجب"], 0, ["L1", "L2"]], ["مرادف كلمة «الجود»:", ["الكرم", "البخل", "الخوف", "الكسل"], 0, ["L1"]], ["ضد كلمة «الصدق»:", ["الكذب", "الأمانة", "الوفاء", "الحق"], 0, ["L1"]], ["في جملة «قرأ الطالبُ الكتابَ» الفاعل هو:", ["الطالبُ", "الكتابَ", "قرأ", "لا يوجد"], 0, ["L1", "L2"]], ["المفعول به في «كتب أحمدُ الدرسَ»:", ["الدرسَ", "أحمدُ", "كتب", "لا يوجد"], 0, ["L1", "L2"]], ["الفاعل يكون دائمًا:", ["مرفوعًا", "منصوبًا", "مجرورًا", "مجزومًا"], 0, ["L2", "L3"]], ["في «الجوُّ جميلٌ» الخبر هو:", ["جميلٌ", "الجوُّ", "لا يوجد", "كلاهما"], 0, ["L2", "L3"]], ["«كان» ترفع الاسم و:", ["تنصب الخبر", "ترفع الخبر", "تجر الخبر", "تجزم الخبر"], 0, ["L2", "L3"]], ["«إنّ» تنصب الاسم و:", ["ترفع الخبر", "تنصب الخبر", "تجر الخبر", "لا تعمل"], 0, ["L2", "L3"]], ["جمع كلمة «كتاب»:", ["كتب", "كتابات فقط", "كاتبون", "مكاتب"], 0, ["L1"]], ["الجملة الاسمية تبدأ بـ:", ["اسم", "فعل", "حرف جر", "ظرف"], 0, ["L1", "L2"]], ["التشبيه في «العلم نورٌ» يسمى تشبيهًا:", ["بليغًا", "تامًّا", "تمثيليًّا", "ضمنيًّا"], 0, ["L3"]], ["المحسّن البديعي في «الليل والنهار»:", ["طباق", "جناس", "سجع", "تورية"], 0, ["L3"]], ["الكلمة الصحيحة:", ["إنشاء الله لمعنى البناء، وإن شاء الله للمشيئة", "إنشاء الله للمشيئة دائمًا", "انشاء الله", "ان شاءلله"], 0, ["L2", "L3"]], ["علامة رفع جمع المذكر السالم:", ["الواو", "الضمة", "الألف", "الياء"], 0, ["L3"]], ["يُكتب العدد «ثلاث» مع المعدود المذكر:", ["ثلاثة", "ثلاث", "ثلاثون", "ثالث"], 0, ["L3"]], ["الكلمة التي تُكتب همزتها على ياء:", ["سُئل", "سأل", "يسأل", "مسؤول"], 0, ["L2", "L3"]]],
      rules: "يُؤدّى الاختبار مرة واحدة خلال موعده.\nلكل سؤال إجابة واحدة صحيحة.",
