    4: '<path d="M12 3.5 21 8.6v12.2L12 26 3 20.8V8.6z" fill="#7B5CD6" stroke="#4E37A0" stroke-width="1.2"/><rect x="7" y="11" width="2.4" height="9.5" rx="1.2" fill="#fff"/><rect x="10.8" y="11" width="2.4" height="9.5" rx="1.2" fill="#fff"/><rect x="14.6" y="11" width="2.4" height="9.5" rx="1.2" fill="#fff"/><rect x="7" y="10" width="10" height="2.2" rx="1.1" fill="#fff"/><circle cx="20.5" cy="3.5" r="2.6" fill="none" stroke="#4E37A0" stroke-width="1.3"/><path d="M17.6 6.2 19 4.8" stroke="#4E37A0" stroke-width="1.3"/>'
