  function nidMap(l, sm, grade) {
    const txt = [l.title_ar, l.title_en, sm && sm.idea, sm && (sm.learn || []).map((x) => x[1]).join(" ")].join(" ");
    let best = null, score = -1, order = 0;
    NID_FW.forEach((A) => A.el.forEach((E) => { const m = (txt.match(new RegExp(E.kw.source, "g")) || []).length; order++; if (m > score) { score = m; best = { A, E }; } }));
    if (!score) best = { A: NID_FW[1], E: NID_FW[1].el[0] };
    const st = (grade || 9) <= 4 ? "p" : grade <= 8 ? "m" : "s";
    return { axis: best.A.ax, el: best.E.n, out: best.E.o[st] };
  }
