    const pts = (learn || []).map((x) => String(x).replace(/^[^\p{L}]+/u, "")).filter(Boolean);
    const foc = (s) => { let w = String(s || "").replace(/^[^\p{L}]+/u, "").replace(/^(أن|To|I can)\s+/i, "").split(/\s+/); if (w.length > 2 && (/^[أي]\S{2,6}$/.test(w[0]) || /^[a-z]+$/i.test(w[0]))) w = w.slice(1); return w.join(" "); };
