    const book = os.book ? scObj.map((x) => x.t) : [];
    const sc = scObj.map((x) => x.t);
    const quran = (ev || []).filter((e) => e.kind === "quran"), hadith = (ev || []).filter((e) => e.kind === "hadith");
    const qPart = pick(quran);
    const smEv = c.ev && typeof c.ev === "object" ? c.ev : null;
    const qref = (e) => (e && e.surah_no && e.ayah_from ? { s: e.surah_no, a1: e.ayah_from, a2: e.ayah_to || e.ayah_from } : null);
    const v1 = P === 2 && qPart[0] ? { text: qPart[0].text_ar, tr: qPart[0].translation_en || "", ref: qPart[0].source || "", q: qref(qPart[0]) }
      : smEv ? { text: smEv.text, tr: smEv.en || "", ref: smEv.src || "", q: null } : quran[0] ? { text: quran[0].text_ar, tr: quran[0].translation_en || "", ref: quran[0].source || "", q: qref(quran[0]) } : null;
    const rec = quran[0] || null;
    const pages = l.book_pages ? (en ? `Textbook ${l.book_pages}` : `الكتاب ${l.book_pages}`) : "";
    const partLbl = P ? tdT(en, `الحصة ${P === 1 ? "الأولى" : "الثانية"} من ${l.periods}`, `Lesson ${P} of ${l.periods}`) : "";
    const S = [];
    S.push({ t: "open", d: { label: tdT(en, "أتلو بتجويد:", "I recite with Tajweed:"), text: rec ? rec.text_ar : "", ref: rec ? rec.source || "" : "" },
      n: tdT(en, "التلاوة (4 دقائق): قراءة نموذجية، ثم ترديد جماعي، ثم أزواج. غيّر الآيات إن كانت التلاوة المقررة اليوم غيرها.", "Recitation (4 min): model, echo, then pairs. Replace the verses if today's recitation differs.") });
    // starter: part 1 = previous lessons; part 2 = first period of this lesson
