    h(`<section class="page-head"><div class="wrap"><h1>⚡ ${CT("تحدٍّ مباشر في الصف", "Live class challenge")}</h1><p class="muted">${CT("اختر الدروس، واعرض الرمز على شاشة الصف، ويجيب الطلاب من أجهزتهم. النقاط للأسرع والأصح.", "Pick lessons, show the code on the class screen, and students answer from their devices. Points for speed and accuracy.")}</p>
      <a class="btn btn-ghost btn-small" href="#/live?join=1">${CT("أنا لاعب: ادخل برمز", "I'm a player: join with a code")}</a></div></section>
      <section class="section"><div class="wrap" style="max-width:820px"><div class="live-setup">
        <div class="bk-row"><label>${CT("الصف", "Grade")}<select id="lvG">${Array.from({ length: 12 }, (_, i) => i + 1).map((n) => `<option value="${n}" ${n === g0 ? "selected" : ""}>Grade ${n}</option>`).join("")}</select></label>
          <label>${CT("المسار", "Track")}<select id="lvT"><option value="native" ${tr0 === "native" ? "selected" : ""}>${CT("الناطقون", "Arabic speakers")}</option><option value="non_native" ${tr0 === "non_native" ? "selected" : ""}>${CT("غير الناطقين", "Non-Arabic speakers")}</option></select></label>
          <label>${CT("عدد الأسئلة", "Questions")}<select id="lvN">${[5, 8, 10, 12, 15, 20, 25, 30, 40].map((n) => `<option ${n === 15 ? "selected" : ""}>${n}</option>`).join("")}</select></label>
          <label>${CT("ثوانٍ لكل سؤال", "Seconds per question")}<select id="lvS">${[10, 15, 20, 30].map((n) => `<option ${n === 20 ? "selected" : ""}>${n}</option>`).join("")}</select></label></div>
        <div class="lv-modes"><label class="lv-mode"><input type="radio" name="lvMode" value="self" checked><span><b>🏁 ${CT("كل طالب بسرعته", "Student-paced")}</b><small>${CT("سباق بالنقاط والجوائز والسلاسل لوقت محدد، مثل «بلوكت». الأكثر حماسًا!", "A timed race with points, bonuses and streaks — like Blooket. The most exciting!")}</small></span></label>
          <label class="lv-mode"><input type="radio" name="lvMode" value="teacher"><span><b>👩‍🏫 ${CT("بإيقاع المعلم", "Teacher-paced")}</b><small>${CT("سؤال واحد للجميع على الشاشة، مثل «كاهوت».", "One question for everyone on screen — like Kahoot.")}</small></span></label>
          <label>${CT("مدة السباق", "Race length")}<select id="lvMin">${[3, 5, 7, 10, 15].map((n) => `<option value="${n}" ${n === 5 ? "selected" : ""}>${n} ${CT("دقائق", "min")}</option>`).join("")}</select></label></div>
        <div id="lvLessons" class="lv-lessons"></div>
        <button class="btn btn-dawn" id="lvGo">${CT("أنشئ التحدّي", "Create the challenge")}</button></div></div></section>`);
    const loadL = async () => {
      const box = document.getElementById("lvLessons"); box.innerHTML = '<p class="muted">…</p>';
      const { data: us } = await sb.from("units").select("id, term, sort_order, title_ar, title_en, lessons(id, code, title_ar, title_en)").eq("year_group", +document.getElementById("lvG").value).eq("track", document.getElementById("lvT").value).eq("subject_id", 1).order("term").order("sort_order");
      box.innerHTML = (us || []).map((u) => `<details ${u.term === bookTermNow() ? "open" : ""}><summary><label><input type="checkbox" data-unit="${u.id}"> ${CT("الوحدة", "Unit")} ${u.sort_order}: ${esc(CT(u.title_ar, u.title_en || u.title_ar))}</label></summary>
        ${(u.lessons || []).sort((a, b) => a.code.localeCompare(b.code)).map((l) => `<label class="lv-l"><input type="checkbox" data-l="${l.id}" data-u="${u.id}"> ${esc(CT(l.title_ar, l.title_en || l.title_ar))}</label>`).join("")}</details>`).join("");
      box.querySelectorAll("[data-unit]").forEach((c) => c.onchange = () => box.querySelectorAll(`[data-u="${c.dataset.unit}"]`).forEach((x) => { x.checked = c.checked; }));
    };
