      const { data, error } = await sb.rpc("live_create", { p_lessons: ids, p_n: +document.getElementById("lvN").value, p_title: null });
      if (error) { toast(/no questions/.test(error.message) ? CT("لا توجد أسئلة لهذه الدروس", "No questions for these lessons") : error.message); return; }
      await sb.from("live_games").select("id").eq("id", data.id); // warm
      try { sessionStorage.setItem("hiraa.live.secs." + data.id, document.getElementById("lvS").value); sessionStorage.setItem("hiraa.live.mode." + data.id, (document.querySelector('input[name="lvMode"]:checked') || {}).value || "self"); sessionStorage.setItem("hiraa.live.min." + data.id, document.getElementById("lvMin").value); } catch (e) {}
      location.hash = "#/live/host/" + data.id;
