          <ol class="race-list">${players.map((p, i) => `<li class="${i < 3 ? "top" + (i + 1) : ""}"><span class="rk">${["🥇", "🥈", "🥉"][i] || i + 1}</span><b>${esc(p.nickname)}</b>${p.streak >= 3 ? `<span class="fire">🔥${p.streak}</span>` : ""}<div class="rbar"><i style="width:${Math.round((p.score / top) * 100)}%"></i></div><em>${p.score}</em></li>`).join("")}</ol>
