  /* ===== cheerful game sounds (respect the volume / mute control) ===== */
  let _sfxAc = null;
  function sfx(kind) {
    try { if (SND.mute || SND.vol === 0) return; _sfxAc = _sfxAc || new (window.AudioContext || window.webkitAudioContext)(); const ac = _sfxAc; if (ac.state === "suspended") ac.resume();
      const t0 = ac.currentTime, note = (f, t, d, type, v) => { const o = ac.createOscillator(), g = ac.createGain(); o.type = type || "sine"; o.frequency.setValueAtTime(f, t0 + t); g.gain.setValueAtTime(0.0001, t0 + t); g.gain.exponentialRampToValueAtTime(v || 0.25, t0 + t + 0.02); g.gain.exponentialRampToValueAtTime(0.0001, t0 + t + d); o.connect(g); g.connect(ac.destination); o.start(t0 + t); o.stop(t0 + t + d + 0.05); };
      const S = { correct: () => { note(660, 0, 0.12, "triangle"); note(880, 0.1, 0.18, "triangle"); },
        streak: () => { [660, 880, 1046].forEach((f, i) => note(f, i * 0.08, 0.16, "triangle")); },
        bonus: () => { [784, 988, 1175, 1568].forEach((f, i) => note(f, i * 0.07, 0.2, "sine", 0.22)); },
        wrong: () => { note(220, 0, 0.18, "sawtooth", 0.12); note(165, 0.14, 0.25, "sawtooth", 0.1); },
        join: () => note(988, 0, 0.12, "sine", 0.15), tick: () => note(1200, 0, 0.05, "square", 0.08),
        start: () => { [523, 659, 784].forEach((f, i) => note(f, i * 0.12, 0.2, "triangle")); note(1046, 0.36, 0.4, "triangle"); },
        fanfare: () => { [523, 659, 784, 1046, 784, 1046].forEach((f, i) => note(f, i * 0.14, i === 5 ? 0.6 : 0.18, "triangle", 0.25)); } };
      (S[kind] || S.correct)(); } catch (e) {}
  }


